// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"abacavir-lamivudin-dolutegravir":{"wirkmechanismus":"Hemmt die Vermehrung von HIV an zwei Stellen. Dolutegravir blockiert die Integrase und verhindert den Einbau der Virus-DNA in das Erbgut der Wirtszelle (Strangtransfer). Abacavir (ein Guanosin-Analogon, aktiv als Carbovir-Triphosphat) und Lamivudin (ein Cytidin-Analogon) werden in den Zellen phosphoryliert, von der Reversen Transkriptase in die Virus-DNA eingebaut und führen zum Kettenabbruch. Die Kombination mehrerer Wirkprinzipien beugt Resistenzen vor.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Übelkeit","Durchfall"],"haeufig":["Überempfindlichkeitsreaktion auf Abacavir (Fieber, Ausschlag, Übelkeit, Bauchschmerzen, Atembeschwerden, Müdigkeit) – lebensbedrohlich möglich","Schlaflosigkeit, abnorme Träume, Albträume, Depression, Angst","Schwindel, Schläfrigkeit, Lethargie","Erbrechen, Blähungen, Bauchschmerzen, Sodbrennen","Hautausschlag, Juckreiz, Haarausfall","Gelenk- und Muskelbeschwerden","Müdigkeit, Schwäche, Fieber, Appetitlosigkeit","Erhöhte Leberwerte und Kreatinkinase (CK), Gewichtszunahme"],"gelegentlich":["Hepatitis (Leberentzündung)","Suizidgedanken oder Suizidversuch, Panikattacken (vor allem bei psychischer Vorerkrankung)","Neutropenie, Anämie, Thrombozytopenie","Erhöhte Triglyceride, erhöhter Blutzucker","Immunrekonstitutionssyndrom"],"selten":["Pankreatitis (Bauchspeicheldrüsenentzündung)","Akutes Leberversagen","Rhabdomyolyse (Muskelzerfall)","Angioödem (Schwellung von Haut und Schleimhäuten)","Laktatazidose (Übersäuerung des Blutes)","Suizid (bei psychischer Vorerkrankung)"],"sehrSelten":["Periphere Neuropathie (Kribbeln, Taubheitsgefühl)","Erythroblastopenie (Aplasie der roten Blutzellen)","Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse"]},"schwangerschaft":"Kann bei klinischer Notwendigkeit angewendet werden. Ein früher vermutetes erhöhtes Risiko für Neuralrohrdefekte durch Dolutegravir zum Zeitpunkt der Empfängnis hat sich in grösseren Untersuchungen nicht klar bestätigt – Schwangerschaft mit der HIV-Fachperson planen.","stillzeit":"HIV-positive Mütter sollen grundsätzlich nicht stillen (Übertragungsrisiko); ein Stillwunsch ist mit der HIV-Fachperson zu besprechen.","hinweise":["Vor Beginn HLA-B*5701-Test; die Warnkarte zur Abacavir-Überempfindlichkeit immer bei sich tragen.","Bei Fieber, Ausschlag, Übelkeit, Atembeschwerden oder starker Müdigkeit sofort ärztlich melden; nach einer Überempfindlichkeitsreaktion nie wieder einnehmen.","Antazida, Mineralstoff- und Eisenpräparate zeitversetzt einnehmen (Triumeq 2 Stunden davor oder 6 Stunden danach).","Einmal täglich mit oder ohne Mahlzeit einnehmen; bei Hepatitis B nicht eigenmächtig absetzen."],"darreichung":["Filmtabletten"]},"abemaciclib":{"wirkmechanismus":"Bremst die Teilung hormonempfindlicher Brustkrebszellen. Abemaciclib hemmt die Cyclin-abhängigen Kinasen 4 und 6 (CDK4 stärker als CDK6); dadurch bleibt das Retinoblastom-Protein unphosphoryliert, und der Zellzyklus stoppt in der G1-Phase. Bei durchgehender Einnahme ohne Pause führt dies zu Wachstumsstillstand und Absterben von Tumorzellen. Abemaciclib wird über CYP3A4 zu ebenfalls wirksamen Metaboliten abgebaut.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Neutropenie, Leukopenie, Anämie, Thrombozytopenie, Lymphopenie","Infektionen","Übelkeit, Erbrechen, Bauchschmerzen, Stomatitis","Appetitlosigkeit, Geschmacksstörungen","Haarausfall, Juckreiz, Hautausschlag","Müdigkeit, Fieber, Schwindel","Erhöhte Leberwerte (ALT, AST), erhöhtes Kreatinin"],"haeufig":["Venöse Thromboembolien (Beinvenenthrombose, Lungenembolie)","Interstitielle Lungenerkrankung, Pneumonitis","Vermehrter Tränenfluss","Febrile Neutropenie","Trockene Haut, Nagelveränderungen","Dyspepsie (Verdauungsbeschwerden)","Muskelschwäche"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen müssen während und mindestens 3 Wochen nach der Behandlung sicher verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Zweimal täglich ohne Pause einnehmen, mit oder ohne Mahlzeit; Grapefruit meiden.","Beim ersten weichen Stuhl sofort ein Mittel gegen Durchfall (z. B. Loperamid nach ärztlicher Anweisung) einnehmen, viel trinken und die Ärztin oder den Arzt informieren.","Schmerzen oder Schwellung eines Beins, plötzliche Atemnot oder Brustschmerzen sofort melden (Thrombose, Lungenembolie).","Blutbild und Leberwerte werden in den ersten Monaten engmaschig kontrolliert."],"darreichung":["Filmtabletten"]},"abirateron":{"wirkmechanismus":"Stoppt die Bildung männlicher Hormone nicht nur in den Hoden, sondern auch in Nebennieren und Tumorgewebe. Abirateronacetat wird im Körper zu Abirateron umgewandelt, das das Enzym CYP17 (17α-Hydroxylase/C17,20-Lyase) irreversibel hemmt. Weil dadurch auch weniger Kortisol entsteht, steigt ACTH und es werden vermehrt Mineralokortikoide gebildet – mit Bluthochdruck, Kaliummangel und Ödemen. Deshalb wird gleichzeitig Prednison oder Prednisolon gegeben.","nebenwirkungen":{"sehrHaeufig":["Hypokaliämie (Kaliummangel)","Hypertonie (Bluthochdruck)","Periphere Ödeme (Wassereinlagerungen)","Harnwegsinfektion","Durchfall","Erhöhte Leberwerte"],"haeufig":["Herzinsuffizienz, Angina pectoris","Vorhofflimmern, Herzrasen","Hypertriglyzeridämie (erhöhte Blutfette)","Sepsis","Dyspepsie (Verdauungsbeschwerden)","Blut im Urin","Hautausschlag","Knochenbrüche"],"gelegentlich":["Nebenniereninsuffizienz","Myopathie, Rhabdomyolyse (Muskelschädigung)"],"selten":["Akutes Leberversagen, fulminante Hepatitis","Allergische Alveolitis (Lungenentzündung)"],"unbekannt":["Herzinfarkt","QT-Verlängerung","Anaphylaxie"]},"schwangerschaft":"Kontraindiziert; nicht für Frauen bestimmt. Männer sollen ein Kondom verwenden (bei schwangerer Partnerin immer, sonst zusätzlich eine weitere Methode) – während und bis 1 Woche nach der Behandlung.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Auf nüchternen Magen einnehmen: mindestens 1 Stunde vor oder 2 Stunden nach dem Essen – mit Nahrung steigt die Aufnahme um ein Vielfaches.","Prednison bzw. Prednisolon gleichzeitig einnehmen und nie eigenmächtig absetzen.","Blutdruck, Kalium und Leberwerte werden regelmässig kontrolliert; Herzklopfen, Schwäche oder Gelbfärbung melden.","Schwangere oder Frauen, die schwanger werden könnten, sollen die Tabletten nur mit Handschuhen anfassen."],"darreichung":["Tabletten","Filmtabletten"]},"abrocitinib":{"wirkmechanismus":"Dämpft die überschiessende Entzündung der Haut und lindert rasch den Juckreiz. Abrocitinib hemmt bevorzugt die Januskinase 1 (JAK1), ein Enzym, das Signale vieler Entzündungsbotenstoffe (u. a. IL-4, IL-13, IL-31, IL-22, Interferon-γ) über den JAK-STAT-Weg ins Zellinnere weiterleitet. Durch die Blockade werden diese Signale abgeschwächt, was Entzündung, Juckreiz und Hautbarrierestörung vermindert. Es wird hauptsächlich über CYP2C19 und CYP2C9 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Übelkeit"],"haeufig":["Lippenherpes (Herpes simplex), Gürtelrose (Herpes zoster)","Kopfschmerzen, Schwindel","Erbrechen, Oberbauchschmerzen","Akne","Thrombozytopenie (Mangel an Blutplättchen)","Erhöhte Kreatinkinase (CK, Muskelenzym)"],"gelegentlich":["Lungenentzündung (Pneumonie)","Lymphopenie (Mangel an Lymphozyten)","Erhöhte Blutfette","Venöse Thromboembolien (Thrombose, Lungenembolie)"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter müssen während der Behandlung und bis 1 Monat nach der letzten Dosis zuverlässig verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Einmal täglich unabhängig vom Essen einnehmen; mit einer Mahlzeit kann Übelkeit geringer sein.","Bei Fieber, Infektzeichen, Bläschenausschlag, Schmerzen oder Schwellung eines Beines, Atemnot oder Brustschmerzen sofort ärztlich abklären lassen.","Regelmässige Kontrollen von Blutbild und Blutfetten sowie der Haut (Hautkrebs-Vorsorge)."],"darreichung":["Filmtabletten"]},"acarbose":{"wirkmechanismus":"Sorgt dafür, dass Zucker aus der Nahrung langsamer ins Blut gelangt. Acarbose hemmt im Dünndarm die Alpha-Glucosidasen (z. B. Saccharase, Maltase, Glucoamylase), die Mehrfach- und Zweifachzucker in Einfachzucker spalten. Die Kohlenhydrate werden dadurch verzögert abgebaut und aufgenommen, der Blutzuckeranstieg nach den Mahlzeiten fällt flacher aus. Acarbose wird kaum ins Blut aufgenommen und löst allein keine Unterzuckerung aus; unverdaute Kohlenhydrate werden im Dickdarm vergoren, was die Blähungen erklärt.","nebenwirkungen":{"sehrHaeufig":["Blähungen (Flatulenz)"],"haeufig":["Durchfall","Magen-Darm- und Bauchschmerzen"],"gelegentlich":["Übelkeit, Erbrechen","Dyspepsie (Verdauungsbeschwerden)","Erhöhte Leberwerte"],"selten":["Ödeme (Wassereinlagerungen)","Gelbsucht (Ikterus)"],"unbekannt":["Darmverschluss (Ileus, Subileus)","Pneumatosis cystoides intestinalis (Gasansammlungen in der Darmwand)","Leberentzündung (Hepatitis)","Thrombozytopenie (Mangel an Blutplättchen)","Überempfindlichkeitsreaktionen der Haut (Ausschlag, Rötung, Nesselsucht)","Akute generalisierte exanthematische Pustulose (schwere Hautreaktion mit Pusteln)"]},"schwangerschaft":"Kontraindiziert; ein Diabetes in der Schwangerschaft wird mit Insulin behandelt.","stillzeit":"Kontraindiziert, da keine ausreichenden Daten vorliegen.","hinweise":["Unmittelbar vor einer Hauptmahlzeit unzerkaut mit etwas Flüssigkeit schlucken oder mit den ersten Bissen zerkauen.","Bei Unterzuckerung Traubenzucker (Glucose) nehmen – Haushaltszucker und Süssgetränke wirken unter Acarbose nur verzögert.","Blähungen sind zu Beginn häufig und lassen meist nach; Diät einhalten und zuckerreiche Speisen meiden."],"darreichung":["Tabletten"]},"acenocoumarol":{"wirkmechanismus":"Hemmt die Blutgerinnung, indem es die Wirkung von Vitamin K in der Leber blockiert. Acenocoumarol hemmt die Vitamin-K-Epoxid-Reduktase (VKORC1); dadurch werden die Gerinnungsfaktoren II, VII, IX und X sowie Protein C und S nicht mehr funktionsfähig gebildet. Die volle Wirkung setzt nach 2–3 Tagen ein, zu Beginn wird oft überlappend Heparin gegeben. Mit einer Halbwertszeit von etwa 8–11 Stunden wirkt es deutlich kürzer als Phenprocoumon, der INR normalisiert sich nach dem Absetzen innert weniger Tage; abgebaut wird es vor allem über CYP2C9, Gegenmittel ist Vitamin K.","nebenwirkungen":{"haeufig":["Blutungen unterschiedlicher Schwere – meist leicht (Zahnfleisch- und Nasenbluten, Blutergüsse, Blut im Urin), seltener schwer (Magen-Darm-Blutung, Hirnblutung)"],"selten":["Appetitlosigkeit, Übelkeit, Erbrechen","Allergische Hautreaktionen (Nesselsucht, Ausschlag, Juckreiz)","Haarausfall"],"sehrSelten":["Hämorrhagische Hautnekrosen (Cumarin-Nekrose), meist bei angeborenem Protein-C-Mangel","Gefässentzündung (Vaskulitis)","Leberschäden"],"unbekannt":["Calciphylaxie (schmerzhafte Hautgeschwüre durch Gefässverkalkung), vor allem bei Nierenkrankheit"]},"schwangerschaft":"Kontraindiziert: Acenocoumarol kann das Kind schädigen (Cumarin-Embryopathie, Blutungen). Frauen im gebärfähigen Alter müssen sicher verhüten; bei Kinderwunsch oder Schwangerschaft umgehend ärztlich auf Heparin umstellen.","stillzeit":"Geht nur in geringen Mengen in die Muttermilch über; Stillen ist nach ärztlicher Abwägung möglich, das Kind erhält vorsorglich Vitamin K.","hinweise":["Regelmässige INR-Kontrollen einhalten; Antikoagulationsausweis mitführen und alle Ärztinnen, Ärzte, Zahnärzte und Apotheken informieren.","Keine neuen Medikamente, auch keine rezeptfreien Schmerzmittel oder pflanzlichen Mittel (z. B. Johanniskraut), ohne Rücksprache – viele verändern den INR.","Ernährung gleichmässig halten: die Menge Vitamin-K-reicher Lebensmittel (Kohl, Spinat, Sauerkraut, grünes Blattgemüse) nicht plötzlich stark ändern; Alkohol nur in kleinen Mengen.","Täglich zur gleichen Zeit einnehmen; bei Zeichen einer Blutung (schwarzer Stuhl, Blut im Urin, starke Kopfschmerzen) sofort ärztliche Hilfe holen."],"darreichung":["Tabletten"]},"acetazolamid":{"wirkmechanismus":"Senkt den Augeninnendruck, indem weniger Kammerwasser gebildet wird. Acetazolamid hemmt das Enzym Carboanhydrase, das im Ziliarkörper des Auges für die Bildung von Bicarbonat und damit von Kammerwasser nötig ist. In der Niere führt dieselbe Hemmung zu einer vermehrten Ausscheidung von Bicarbonat, Natrium, Kalium und Wasser. Daraus ergeben sich eine leichte harntreibende Wirkung und eine metabolische Azidose (Übersäuerung des Blutes).","nebenwirkungen":{"unbekannt":["Kribbeln oder Taubheitsgefühl in Händen, Füssen und um den Mund (Parästhesien)","Geschmacksstörungen, Appetitlosigkeit, Übelkeit, Erbrechen, Durchfall","Vermehrtes Wasserlassen, Nierensteine","Müdigkeit, Schläfrigkeit, Verwirrtheit, Depression, Reizbarkeit","Metabolische Azidose, Kalium- und Natriummangel","Vorübergehende Kurzsichtigkeit","Blutbildstörungen (Agranulozytose, Thrombozytopenie, aplastische Anämie)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse), Lichtempfindlichkeit"]},"schwangerschaft":"Im Tierversuch fruchtschädigend. Nicht anwenden, besonders im ersten Schwangerschaftsdrittel, ausser bei zwingender ärztlicher Notwendigkeit.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung in der Stillzeit nicht empfohlen.","hinweise":["Reichlich trinken, um Nierensteinen vorzubeugen.","Bei längerer Einnahme Blutbild und Elektrolyte (Kalium, Natrium) regelmässig kontrollieren lassen.","Kann Müdigkeit, Schwindel und vorübergehende Kurzsichtigkeit verursachen – Vorsicht beim Autofahren."],"darreichung":["Tabletten"]},"acetylcystein":{"wirkmechanismus":"Verflüssigt zähen Schleim, sodass er leichter abgehustet werden kann. Die freie Sulfhydryl-Gruppe (SH-Gruppe) spaltet Disulfidbrücken der Schleim-Glykoproteine und senkt so die Zähigkeit des Bronchialsekrets. Als Gegenmittel bei Paracetamolvergiftung liefert Acetylcystein Cystein für die Neubildung von Glutathion in der Leber; Glutathion bindet den giftigen Paracetamol-Abbaustoff NAPQI und macht ihn unschädlich.","nebenwirkungen":{"gelegentlich":["Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Mundschleimhautentzündung (Stomatitis)","Überempfindlichkeitsreaktionen: Nesselsucht, Ausschlag, Juckreiz, Angioödem","Kopfschmerzen, Ohrensausen (Tinnitus)","Herzrasen (Tachykardie), Blutdruckabfall","Fieber"],"selten":["Bronchospasmus (Verkrampfung der Atemwege), Atemnot – v. a. bei Asthma","Verdauungsbeschwerden (Dyspepsie)"],"sehrSelten":["Anaphylaxie bis zum Schock","Blutungen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, Lyell-Syndrom)"],"unbekannt":["Gesichtsschwellung","Bei Infusion als Gegenmittel: anaphylaktoide Reaktionen (Hautrötung, Juckreiz, Atemnot, Blutdruckabfall)"]},"schwangerschaft":"Begrenzte Daten ohne Hinweise auf Fruchtschädigung; als Schleimlöser nur nach ärztlicher Abwägung. Bei einer Paracetamolvergiftung wird es auch in der Schwangerschaft eingesetzt.","stillzeit":"Keine Daten zum Übergang in die Muttermilch; als Schleimlöser nur nach ärztlicher Abwägung.","hinweise":["Brausetabletten und Granulat in Wasser auflösen; ausreichend trinken. Zu Beginn kann sich der Auswurf vermehren – das ist erwünscht.","Antibiotika zum Einnehmen im Abstand von mindestens 2 Stunden einnehmen.","Nicht mit Hustenstillern kombinieren.","Ein leichter Schwefelgeruch der Zubereitung ist normal."],"darreichung":["Brausetabletten","Granulat zum Einnehmen","Sirup","Injektionslösung (Infusion)"]},"acetylsalicylsaeure":{"wirkmechanismus":"Hemmt die Bildung von Botenstoffen, die Schmerz, Fieber und Entzündung auslösen. Acetylsalicylsäure acetyliert die Cyclooxygenasen COX-1 und COX-2 irreversibel und blockiert so die Prostaglandinsynthese. In niedriger Dosis (75–100 mg pro Tag) steht die Hemmung der Thromboxan-A2-Bildung in den Blutplättchen im Vordergrund: Weil Thrombozyten keinen Zellkern haben und das Enzym nicht nachbilden können, hält die Hemmung ihre ganze Lebensdauer von 7–10 Tagen an.","nebenwirkungen":{"haeufig":["Magen-Darm-Beschwerden wie Sodbrennen, Übelkeit, Bauchschmerzen","Dyspepsie (Verdauungsbeschwerden)","Geringe Blutverluste aus dem Magen-Darm-Trakt (Mikroblutungen)"],"gelegentlich":["Überempfindlichkeitsreaktionen der Haut (Ausschlag, Juckreiz, Nesselsucht)","Magen-Darm-Blutungen","Nasenbluten, Zahnfleischbluten"],"selten":["Magen-Darm-Geschwüre, Durchbruch (Perforation)","Bronchospasmus (Verkrampfung der Atemwege) bei Analgetika-Asthma","Schwere Blutungen, z. B. Hirnblutung","Anaphylaxie (schwere allergische Reaktion)","Schwere Hautreaktionen"],"sehrSelten":["Erhöhte Leberwerte","Nierenfunktionsstörungen","Hypoglykämie (Unterzuckerung)","Reye-Syndrom bei Kindern"],"unbekannt":["Schwindel und Ohrensausen (Tinnitus) als Zeichen einer Überdosierung","Eisenmangelanämie durch verborgene Blutungen","Hämolyse (Blutzerfall) bei G6PD-Mangel"]},"schwangerschaft":"Im 1. und 2. Drittel nur nach ärztlicher Abwägung und so kurz und niedrig dosiert wie möglich. Im letzten Drittel in Dosen über 100 mg pro Tag kontraindiziert; niedrig dosierte ASS (z. B. zur Vorbeugung einer Präeklampsie) nur auf ärztliche Verordnung.","stillzeit":"Gelegentliche Einnahme niedriger Dosen ist vertretbar. Bei regelmässiger Einnahme höherer Dosen soll abgestillt werden.","hinweise":["Vor Operationen und Zahnbehandlungen die Einnahme angeben: die Blutungsneigung hält 7–10 Tage an.","Nach dem Essen mit reichlich Flüssigkeit einnehmen; Alkohol erhöht das Risiko für Magenblutungen.","Niedrig dosierte ASS zur Herzinfarkt- oder Schlaganfallvorbeugung nicht eigenmächtig absetzen.","Kindern und Jugendlichen mit Fieber nur auf ärztlichen Rat geben (Reye-Syndrom)."],"darreichung":["Tabletten","Brausetabletten","Magensaftresistente Tabletten","Granulat (Beutel)","Injektionslösung"]},"aciclovir":{"wirkmechanismus":"Hemmt die Vermehrung von Herpesviren in befallenen Zellen. Aciclovir wird bevorzugt in virusinfizierten Zellen durch die virale Thymidinkinase und danach durch zelluläre Enzyme zu Aciclovirtriphosphat umgewandelt. Dieses hemmt die virale DNA-Polymerase und führt nach Einbau in die Virus-DNA zum Kettenabbruch. Gesunde Zellen bleiben weitgehend verschont; ruhende (latente) Viren werden nicht beseitigt, Rückfälle bleiben daher möglich.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel (Tabletten/Infusion)","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen (Tabletten/Infusion)","Juckreiz, Hautausschlag, Lichtempfindlichkeit (Tabletten/Infusion)","Müdigkeit, Fieber (Tabletten/Infusion)","Venenentzündung an der Infusionsstelle, Anstieg von Leber- und Nierenwerten (Infusion)"],"gelegentlich":["Brennen, Stechen, Trockenheit oder Schuppung der Haut (Crème)","Nesselsucht, beschleunigter diffuser Haarausfall (Tabletten/Infusion)"],"selten":["Anaphylaxie (schwere allergische Reaktion), Angioödem","Atemnot","Erhöhte Leber- und Nierenwerte (Tabletten)","Hautrötung, Kontaktdermatitis (Crème)"],"sehrSelten":["Anämie, Leukopenie, Thrombozytopenie","Verwirrtheit, Halluzinationen, Unruhe, Zittern, Ataxie, Sprechstörungen, Krampfanfälle, Schläfrigkeit, Enzephalopathie, Koma – meist bei eingeschränkter Nierenfunktion","Hepatitis, Gelbsucht","Akutes Nierenversagen, Nierenschmerzen"]},"schwangerschaft":"Grosse Schwangerschaftsregister zeigen kein erhöhtes Fehlbildungsrisiko. Tabletten oder Infusion nach ärztlicher Abwägung; die Crème kann angewendet werden.","stillzeit":"Geht in die Muttermilch über; die Mengen gelten als unbedenklich, Stillen ist in der Regel möglich. Crème nicht an der Brust auftragen.","hinweise":["Behandlung so früh wie möglich beginnen – bei Lippenherpes bei den ersten Anzeichen (Kribbeln, Spannungsgefühl).","Während der Behandlung mit Tabletten oder Infusion ausreichend trinken.","Crème mit sauberen Fingern oder Wattestäbchen auftragen, danach Hände waschen; Bläschen nicht aufstechen.","Herpes ist ansteckend: Küssen und Oralverkehr bei Lippenherpes vermeiden, bei Genitalherpes Kondome verwenden."],"darreichung":["Tabletten","Suspension zum Einnehmen","Crème","Infusionslösung (Spital)"]},"acoramidis":{"wirkmechanismus":"Verhindert, dass ein Transporteiweiss im Blut zerfällt und als Amyloid im Herzmuskel abgelagert wird. Acoramidis bindet an die Thyroxin-Bindungsstellen von Transthyretin (TTR) und stabilisiert dessen Viererstruktur (Tetramer). Damit wird der Zerfall in einzelne Untereinheiten, der geschwindigkeitsbestimmende Schritt der Amyloidbildung, weitgehend gehemmt. Bereits gebildete Ablagerungen werden dadurch nicht abgebaut.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Gicht"],"haeufig":["Oberbauchschmerzen"]},"schwangerschaft":"Nicht empfohlen, da keine Daten vorliegen; Frauen im gebärfähigen Alter sollen während der Behandlung verhüten.","stillzeit":"Nicht stillen – keine Daten, ein Risiko für den Säugling kann nicht ausgeschlossen werden.","hinweise":["Regelmässig einnehmen, unabhängig von den Mahlzeiten.","Herz- und Nierenfunktion werden ärztlich regelmässig kontrolliert.","Vor Beginn neuer Medikamente die Ärztin oder den Arzt informieren – Wechselwirkungen sind noch wenig untersucht."],"darreichung":["Filmtabletten"]},"adalimumab":{"wirkmechanismus":"Bremst Entzündungen in Gelenken, Haut, Darm und Auge, indem es einen zentralen Entzündungsbotenstoff ausschaltet. Adalimumab ist ein vollständig humaner monoklonaler IgG1-Antikörper, der TNF-alpha spezifisch bindet und dessen Wirkung an den Zellrezeptoren p55 und p75 blockiert. Dadurch sinken Entzündungsmarker und die Aktivität entzündlicher Zellen. Gleichzeitig wird die Abwehr gegen Infektionen, besonders Tuberkulose, geschwächt.","nebenwirkungen":{"sehrHaeufig":["Infektionen der Atemwege (auch Lungenentzündung, Nasennebenhöhlenentzündung)","Reaktionen an der Einstichstelle (Rötung, Schmerzen, Schwellung)","Kopfschmerzen","Bauchschmerzen, Übelkeit, Erbrechen","Erhöhte Leberwerte","Hautausschlag","Muskel- und Skelettschmerzen","Leukopenie, Anämie, erhöhte Blutfette"],"haeufig":["Schwere Infektionen wie Sepsis, Pilzinfektionen, Grippe, Harnwegs- und Hautinfektionen","Nicht-melanozytärer Hautkrebs, gutartige Tumoren","Thrombozytopenie, Leukozytose","Überempfindlichkeitsreaktionen","Stimmungsschwankungen, Angst, Schlaflosigkeit","Bluthochdruck, Herzrasen","Neue oder verschlechterte Psoriasis, Juckreiz, Nesselsucht","Fieber, Ödeme"],"gelegentlich":["Tuberkulose und opportunistische Infektionen","Lymphom, Melanom, solide Tumoren","Multiple Sklerose, Neuropathie, Zittern","Herzrhythmusstörungen, Herzinsuffizienz","Lungenembolie, interstitielle Lungenerkrankung","Pankreatitis, Gallenblasenentzündung","Lupus erythematodes, Vaskulitis (Gefässentzündung)","Sarkoidose"],"selten":["Leukämie","Panzytopenie","Demyelinisierende Erkrankungen wie Sehnerventzündung oder Guillain-Barré-Syndrom","Hepatitis, autoimmune Hepatitis, Hepatitis-B-Reaktivierung","Darmdurchbruch (Perforation)","Stevens-Johnson-Syndrom, Angioödem, Erythema multiforme","Anaphylaxie (schwere allergische Reaktion)","Lungenfibrose"],"unbekannt":["Hepatosplenisches T-Zell-Lymphom","Merkelzellkarzinom (seltener Hautkrebs), Kaposi-Sarkom","Leberversagen","Verschlechterung einer Dermatomyositis"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung. Adalimumab passiert die Plazenta; Säuglinge, die im Mutterleib exponiert waren, sollen bis 5 Monate nach der letzten Gabe in der Schwangerschaft keine Lebendimpfungen erhalten.","stillzeit":"Geht nur in sehr geringen Mengen in die Muttermilch über; Stillen ist möglich.","hinweise":["Vor Beginn auf Tuberkulose und Hepatitis B testen und den Impfstatus vervollständigen lassen.","Bei Fieber, anhaltendem Husten, Gewichtsverlust oder Nachtschweiss rasch ärztlich abklären lassen.","Regelmässige Hautkontrollen und Sonnenschutz (Hautkrebsrisiko).","Im Kühlschrank lagern; kurzzeitig (bis 14 Tage) bei Raumtemperatur bis 25 °C möglich."],"darreichung":["Injektionslösung (Fertigspritze, Fertigpen)"]},"adapalen":{"wirkmechanismus":"Normalisiert die Verhornung in den Haarfollikeln, sodass sich weniger Mitesser bilden und bestehende sich lösen. Adapalen ist ein Retinoid der dritten Generation (Naphthoesäure-Abkömmling), das gezielt an die Retinsäure-Rezeptoren RAR-beta und RAR-gamma der Haut bindet und die Ausreifung der Follikelzellen reguliert. Zusätzlich hemmt es Entzündungsvorgänge in der Haut. Die Aufnahme in den Körper ist sehr gering.","nebenwirkungen":{"haeufig":["Trockene Haut","Hautreizung, Rötung (Erythem)","Brennen oder Stechen der Haut","Schuppung (Hautabschälung)"],"gelegentlich":["Juckreiz","Kontaktdermatitis","Sonnenbrand","Vorübergehende Verschlechterung der Akne"],"unbekannt":["Allergische Kontaktdermatitis, Schwellung von Gesicht oder Augenlidern, Angioödem","Hellere oder dunklere Hautverfärbung","Schmerzen der Haut","Verbrennungen an der Auftragsstelle"]},"schwangerschaft":"Kontraindiziert. Auch wenn nur wenig Wirkstoff in den Körper gelangt, gelten Retinoide als potenziell fruchtschädigend; bei Eintritt einer Schwangerschaft die Behandlung beenden.","stillzeit":"Nach Abwägung möglich, da kaum Wirkstoff ins Blut gelangt; nicht auf die Brust auftragen.","hinweise":["Einmal täglich abends dünn auf die gereinigte, trockene Haut auftragen.","Die Wirkung zeigt sich nach 4–8 Wochen; anfangs kann sich die Akne vorübergehend verschlechtern.","Sonnenschutz verwenden und Solarium meiden.","Epiduo enthält Benzoylperoxid und kann Haare und Textilien bleichen."],"darreichung":["Gel","Creme"]},"adapalen-benzoylperoxid":{"wirkmechanismus":"Löst Mitesser, wirkt entzündungshemmend und tötet Aknebakterien ab. Adapalen ist ein Retinoid, das an Retinsäurerezeptoren (RAR-beta/-gamma) der Haut bindet und die Verhornung der Talgdrüsenausgänge normalisiert. Benzoylperoxid setzt Sauerstoffradikale frei, die Cutibacterium acnes abtöten, ohne dass Resistenzen entstehen, und wirkt leicht schälend.","nebenwirkungen":{"haeufig":["Trockene Haut","Hautreizung (irritative Kontaktdermatitis)","Brennen und Stechen der Haut","Rötung, Schuppung"],"gelegentlich":["Juckreiz","Sonnenbrand"],"unbekannt":["Allergische Kontaktdermatitis","Schwellung von Gesicht oder Augenlidern","Engegefühl im Hals, Atemnot, Anaphylaxie (schwere allergische Reaktion)","Verbrennungsähnliche Hautschäden an der Auftragsstelle","Hautverfärbung (Hypo-/Hyperpigmentierung)"]},"schwangerschaft":"Kontraindiziert: Retinoide können das ungeborene Kind schädigen. Bei Eintreten einer Schwangerschaft sofort absetzen.","stillzeit":"Nur nach ärztlicher Abwägung; nicht auf die Brust auftragen, damit der Säugling nicht in Kontakt kommt.","hinweise":["Einmal täglich abends dünn auf die gereinigte, trockene Haut auftragen; danach Hände waschen.","Benzoylperoxid bleicht Haare, Textilien und Bettwäsche.","Bei starker Reizung seltener auftragen oder pausieren; Feuchtigkeitscreme und Sonnenschutz verwenden.","Eine Besserung zeigt sich meist erst nach 1–4 Wochen."],"darreichung":["Gel"]},"adenosin":{"wirkmechanismus":"Unterbricht für wenige Sekunden die elektrische Überleitung im Herzen und beendet so kreisende Erregungen, die Herzrasen verursachen. Adenosin aktiviert A1-Rezeptoren im AV-Knoten und Sinusknoten; dadurch öffnen sich Kaliumkanäle, die Zellen werden hyperpolarisiert und die AV-Überleitung wird kurzzeitig blockiert. Über A2-Rezeptoren erweitert es zudem Blutgefässe. Adenosin wird im Blut innerhalb von weniger als 10 Sekunden abgebaut, weshalb es als schneller Bolus gespritzt wird und die Wirkung nur kurz anhält.","nebenwirkungen":{"sehrHaeufig":["Hautrötung (Flush)","Bradykardie, kurze Herzpausen (Asystolie), AV-Block, Extraschläge aus Vorhöfen oder Kammern","Atemnot","Druck- oder Schmerzgefühl in der Brust"],"haeufig":["Kopfschmerzen","Schwindel, Benommenheit","Übelkeit","Angstgefühl","Brennendes Gefühl"],"gelegentlich":["Verschwommenes Sehen","Herzklopfen","Schwitzen","Metallischer Geschmack","Hyperventilation","Druckgefühl im Kopf"],"sehrSelten":["Schwere Bradykardie","Vorhofflimmern, Kammerflimmern, Torsade de pointes","Bronchospasmus","Reaktionen an der Injektionsstelle"],"unbekannt":["Herzstillstand, teils tödlich","Herzinfarkt","Atemstillstand","Krampfanfälle","Bewusstlosigkeit, Ohnmacht (Synkope)","Blutdruckabfall","Erbrechen","Anaphylaktische Reaktion, Angioödem"]},"schwangerschaft":"Nur wenige Daten; nur anwenden, wenn der Nutzen das mögliche Risiko klar überwiegt.","stillzeit":"Keine Daten; wegen der sehr kurzen Wirkdauer ist ein Risiko für den Säugling unwahrscheinlich – Anwendung nach ärztlicher Abwägung.","hinweise":["Wird nur unter EKG-Überwachung mit bereitstehender Notfallausrüstung gegeben.","Ein kurzes Engegefühl in der Brust, Atemnot und Hitzegefühl sind häufig und verschwinden meist innerhalb einer Minute.","Kaffee, Tee, Cola und Energydrinks können die Wirkung abschwächen."],"darreichung":["Injektionslösung"]},"adrenalin":{"wirkmechanismus":"Hebt den Blutdruck, öffnet die Atemwege und bremst die allergische Reaktion innert Minuten. Adrenalin stimuliert Alpha-Rezeptoren (Gefässverengung, Abschwellen von Schleimhaut-Ödemen) sowie Beta-1-Rezeptoren (stärkere und schnellere Herzschläge) und Beta-2-Rezeptoren (Erweiterung der Bronchien). Zudem hemmt es die Freisetzung von Histamin und anderen Entzündungsstoffen aus Mastzellen. Die Wirkung tritt nach Injektion in den Oberschenkelmuskel rasch ein, hält aber nur kurz an.","nebenwirkungen":{"selten":["Stress-Kardiomyopathie (Takotsubo-Syndrom)"],"unbekannt":["Herzklopfen, Herzrasen (Tachykardie)","Herzrhythmusstörungen bis Kammerflimmern","Angina pectoris (Brustenge), Myokardischämie","Blutdruckanstieg, Gefässverengung, Blässe","Angst, Unruhe, Zittern, Kopfschmerzen, Schwindel, Halluzinationen","Schwitzen, Übelkeit, Erbrechen, Schwäche","Hyperglykämie (erhöhter Blutzucker), Hypokaliämie (Kaliummangel), metabolische Azidose","Bronchospasmus","Verletzung oder Infektion an der Injektionsstelle; Durchblutungsstörung bei versehentlicher Injektion in Finger, Hände oder Füsse"]},"schwangerschaft":"Bei Anaphylaxie oder Wiederbelebung lebensrettend und deshalb auch in der Schwangerschaft anzuwenden; Adrenalin kann die Durchblutung der Plazenta vorübergehend vermindern.","stillzeit":"Adrenalin wird über den Darm des Säuglings kaum aufgenommen; die Notfallanwendung ist in der Stillzeit erlaubt.","hinweise":["Im Notfall nicht zögern: Pen in die Aussenseite des Oberschenkels drücken, auch durch die Kleidung; danach Notruf 144 wählen und liegen bleiben (bei Atemnot sitzen).","Immer zwei Adrenalin-Pens dabeihaben; tritt nach 5–15 Minuten keine Besserung ein, den zweiten Pen anwenden.","Nie in Finger, Hände, Füsse oder ein Blutgefäss injizieren.","Verfalldatum regelmässig prüfen, Pen vor Hitze und Kälte schützen; verfärbte oder trübe Lösung nicht verwenden."],"darreichung":["Fertigpen (Autoinjektor)","Injektionslösung","Fertigspritze"]},"aflibercept":{"wirkmechanismus":"Fängt Wachstumsfaktoren ab, die krankhafte und undichte Blutgefässe entstehen lassen. Aflibercept ist ein Fusionsprotein aus Teilen der VEGF-Rezeptoren 1 und 2 und dem Fc-Teil von menschlichem IgG1. Es wirkt als löslicher «Köderrezeptor» und bindet VEGF-A, VEGF-B und den Plazenta-Wachstumsfaktor (PlGF) mit hoher Affinität. Im Auge vermindert dies Gefässneubildung und Netzhautschwellung; bei Krebs drosselt es die Blutversorgung des Tumors.","nebenwirkungen":{"sehrHaeufig":["Auge: verminderte Sehschärfe, Netzhautblutung, Bindehautblutung, Augenschmerzen","Zaltrap: Neutropenie, Leukopenie, Thrombozytopenie (Blutbildveränderungen)","Zaltrap: Bluthochdruck, Blutungen (v. a. Nasenbluten)","Zaltrap: Durchfall, Mundschleimhautentzündung, Bauchschmerzen","Zaltrap: Appetit- und Gewichtsverlust, Erschöpfung, Kopfschmerzen, Heiserkeit","Zaltrap: Eiweiss im Urin, erhöhte Leberwerte und erhöhtes Kreatinin"],"haeufig":["Auge: Riss oder Abhebung des retinalen Pigmentepithels, Glaskörperblutung","Auge: grauer Star (Katarakt), erhöhter Augeninnendruck, Glaskörpertrübungen","Auge: Hornhautschäden, Fremdkörpergefühl, verschwommenes Sehen","Zaltrap: Fieber bei Neutropenie, Infektionen","Zaltrap: Venen- und Arterienthrombosen (z. B. Lungenembolie)","Zaltrap: Fisteln, Hand-Fuss-Syndrom, Austrocknung"],"gelegentlich":["Auge: Endophthalmitis (schwere Infektion im Augeninneren), Netzhautablösung oder -riss","Auge: Entzündung im Augeninneren (Uveitis, Iritis)","Überempfindlichkeitsreaktionen (unter Zaltrap häufig)","Zaltrap: Magen-Darm-Durchbruch (Perforation), Wundheilungsstörungen","Zaltrap: nephrotisches Syndrom, thrombotische Mikroangiopathie"],"selten":["Auge: Erblindung, Eiteransammlung in der vorderen Augenkammer, Linsenverletzung durch die Injektion"],"unbekannt":["Auge: Skleritis (Entzündung der Lederhaut)","Zaltrap: Kiefernekrose","Zaltrap: posteriores reversibles Enzephalopathie-Syndrom (PRES; Kopfschmerzen, Verwirrtheit, Sehstörungen, Krampfanfälle)"]},"schwangerschaft":"Eylea nur anwenden, wenn der Nutzen das Risiko für das Ungeborene überwiegt. Zaltrap nur bei zwingender Notwendigkeit (im Tierversuch fruchtschädigend); Frauen und Männer verhüten während und mindestens 6 Monate nach der Behandlung.","stillzeit":"Während der Behandlung nicht stillen; ein Übergang in die Muttermilch ist nicht ausgeschlossen.","hinweise":["Nach einer Injektion ins Auge bei zunehmenden Schmerzen, Rötung, Lichtempfindlichkeit oder Sehverschlechterung sofort die Augenärztin oder den Augenarzt aufsuchen.","Nach der Injektion ins Auge kann das Sehen vorübergehend gestört sein – bis zur Erholung nicht Auto fahren.","Unter Zaltrap werden Blutdruck, Urin (Eiweiss) und Blutbild regelmässig kontrolliert; geplante Operationen und Zahneingriffe vorher besprechen."],"darreichung":["Injektionslösung zur Injektion in den Glaskörper (Durchstechflasche, Fertigspritze)","Konzentrat zur Herstellung einer Infusionslösung (Zaltrap)"]},"agalsidase-alfa":{"wirkmechanismus":"Ersetzt ein fehlendes Enzym, damit sich ein Fettstoff nicht mehr in Gefässen, Nieren, Herz und Nerven ablagert. Agalsidase alfa ist eine in einer menschlichen Zelllinie hergestellte Alpha-Galactosidase A. Sie wird über Mannose-6-Phosphat-Rezeptoren in die Zellen aufgenommen und spaltet in den Lysosomen das angehäufte Globotriaosylceramid (Gb3). Dadurch nehmen die Ablagerungen etwa in den Gefässwänden und in der Niere ab.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Übelkeit","Schüttelfrost, Fieber, Schmerzen und Unwohlsein","Müdigkeit"],"haeufig":["Schwindel, Geschmacksstörung, Nervenschmerzen, Zittern, Taubheits- und Kribbelgefühle","Vermehrter Tränenfluss, Ohrgeräusche (Tinnitus)","Herzrasen, Herzklopfen","Hautrötung mit Hitzegefühl (Flush), Bluthochdruck","Husten, Heiserkeit, Engegefühl im Hals, Atemnot","Durchfall, Erbrechen, Bauchschmerzen","Ausschlag, Juckreiz, Akne","Muskel-, Gelenk-, Rücken- und Gliederschmerzen, Wassereinlagerungen in den Beinen"],"unbekannt":["Anaphylaxie und andere Überempfindlichkeitsreaktionen","Herzrhythmusstörungen (z. B. Vorhofflimmern), Durchblutungsstörungen des Herzmuskels, Herzschwäche","Erniedrigte Sauerstoffsättigung"]},"schwangerschaft":"Nur sehr begrenzte Erfahrungen. Anwendung nur nach sorgfältiger ärztlicher Abwägung.","stillzeit":"Nicht bekannt, ob Agalsidase alfa in die Muttermilch übergeht. Anwendung nur nach ärztlicher Abwägung.","hinweise":["Wird alle 2 Wochen als Infusion in eine Vene gegeben (rund 40 Minuten); nach Schulung ist eine Heiminfusion möglich.","Infusionsreaktionen treten vor allem in den ersten Behandlungsmonaten auf – Beschwerden sofort melden.","Nierenfunktion, Herz und Antikörper werden regelmässig kontrolliert."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"agalsidase-beta":{"wirkmechanismus":"Ersetzt ein fehlendes Enzym, damit sich ein Fettstoff nicht mehr in Gefässen, Nieren, Herz und Nerven ablagert. Agalsidase beta ist eine in Hamster-Eierstockzellen gentechnisch hergestellte Alpha-Galactosidase A. Sie wird über Mannose-6-Phosphat-Rezeptoren in die Zellen aufgenommen und spaltet in den Lysosomen das angehäufte Globotriaosylceramid (Gb3). Dadurch nehmen die Ablagerungen vor allem in den Gefässwänden von Niere, Herz und Haut ab.","nebenwirkungen":{"sehrHaeufig":["Schüttelfrost, Fieber, Kältegefühl","Übelkeit, Erbrechen","Kopfschmerzen, Kribbeln (Parästhesien)"],"haeufig":["Schwindel, Schläfrigkeit, Taubheitsgefühl, Brennen, Ohnmacht","Herzrasen, Herzklopfen, Bradykardie (langsamer Puls)","Hautrötung mit Hitzegefühl, Bluthochdruck oder Blutdruckabfall, Blässe","Atemnot, verstopfte Nase, Engegefühl im Hals, pfeifende Atmung, Husten","Bauchschmerzen, Magenbeschwerden, Durchfall","Juckreiz, Nesselsucht, Ausschlag, Hautrötung","Glieder-, Muskel-, Rücken- und Gelenkschmerzen","Müdigkeit, Brustschmerzen, Schwellungen von Gesicht und Gliedern"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Leukozytoklastische Vaskulitis (Entzündung kleiner Blutgefässe)","Sauerstoffmangel (Hypoxie)"]},"schwangerschaft":"Nur sehr begrenzte Erfahrungen. Anwendung nur, wenn eindeutig nötig.","stillzeit":"Agalsidase beta kann in die Muttermilch übergehen. Anwendung nur nach ärztlicher Abwägung.","hinweise":["Wird alle 2 Wochen als Infusion in eine Vene gegeben; nach Schulung ist eine Heiminfusion möglich.","Fieber, Schüttelfrost, Atemnot oder Ausschlag während oder nach der Infusion sofort melden.","Nierenfunktion, Herz und Antikörper werden regelmässig kontrolliert."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Infusionslösung"]},"aktivkohle":{"wirkmechanismus":"Bindet viele Giftstoffe an seiner Oberfläche, sodass sie mit dem Stuhl ausgeschieden statt ins Blut aufgenommen werden. Aktivkohle ist eine hochporöse Kohle mit einer inneren Oberfläche von rund 1000 Quadratmetern pro Gramm, an die sich Medikamente und Gifte physikalisch anlagern (Adsorption). Wiederholte Gaben unterbrechen zudem den Kreislauf von Stoffen, die über Galle oder Darmwand erneut in den Darm gelangen. Aktivkohle selbst wird nicht aufgenommen. Schlecht oder gar nicht gebunden werden Alkohole, Säuren und Laugen, Eisen, Lithium und andere Metallsalze, Cyanid sowie Erdöldestillate.","nebenwirkungen":{"sehrHaeufig":["Schwarzfärbung des Stuhls (harmlos)"],"haeufig":["Erbrechen","Verstopfung (Obstipation)"],"unbekannt":["Durchfall (v. a. zusammen mit Abführmitteln)","Aspiration (Einatmen) von Kohle mit Lungenentzündung","Darmverschluss durch Kohleansammlungen bei wiederholter Gabe"]},"schwangerschaft":"Aktivkohle wird nicht aufgenommen; bei Vergiftungen in der Schwangerschaft anwendbar.","stillzeit":"Anwendung in der Stillzeit möglich.","hinweise":["Bei Vergiftungsverdacht sofort Tox Info Suisse (Notruf 145) oder den Notruf 144 kontaktieren; Kohle wirkt am besten innerhalb der ersten Stunde nach der Giftaufnahme.","Der Stuhl färbt sich schwarz – das ist harmlos.","Andere Medikamente mindestens 2 Stunden vor oder nach der Kohle einnehmen."],"darreichung":["Granulat zur Herstellung einer Suspension zum Einnehmen","Kapseln (Kombination mit Hefe)"]},"alanyl-glutamin":{"wirkmechanismus":"Liefert dem Körper die Aminosäure Glutamin, die bei schweren Krankheiten, grossen Operationen oder Verletzungen vermehrt verbraucht wird. Freies Glutamin ist in Infusionslösungen schlecht löslich und nicht stabil; als Dipeptid mit Alanin ist es gut löslich und haltbar. Im Körper wird Alanyl-Glutamin rasch in Alanin und Glutamin gespalten. Glutamin dient unter anderem als Energielieferant für Darm- und Immunzellen sowie als Baustein für Eiweisse und das Antioxidans Glutathion.","nebenwirkungen":{},"schwangerschaft":"Keine ausreichenden Erfahrungen; während der Schwangerschaft nicht empfohlen.","stillzeit":"Keine Erfahrungen; während der Stillzeit nicht empfohlen.","hinweise":["Wird nur im Spital als Zusatz zu einer Aminosäure-Infusion bzw. zusammen mit Infusions- oder Sondenernährung gegeben, nicht als alleinige Infusion.","Die Anwendungsdauer beträgt in der Regel höchstens 3 Wochen.","Während der Behandlung werden Leberwerte, Nierenwerte und Säure-Basen-Haushalt regelmässig kontrolliert."],"darreichung":["Infusionskonzentrat (Zusatz zu Infusionslösungen)"]},"albumin-human":{"wirkmechanismus":"Hält Flüssigkeit in den Blutgefässen und stabilisiert so den Kreislauf. Albumin macht über die Hälfte der Eiweisse im Blutplasma aus und bestimmt rund 80 % des kolloidosmotischen (onkotischen) Drucks, der Wasser in den Gefässen bindet. Eine 4–5 %-Lösung entspricht dem Plasma, 20–25 %-Lösungen ziehen zusätzlich Wasser aus dem Gewebe in die Gefässe (rund 18 ml Wasser pro Gramm Albumin). Albumin dient im Blut zudem als Transporteiweiss für Hormone, Bilirubin und viele Arzneimittel.","nebenwirkungen":{"selten":["Flush (Hitzegefühl, Hautrötung)","Nesselsucht","Fieber","Übelkeit"],"sehrSelten":["Anaphylaktischer Schock (schwere allergische Reaktion)"],"unbekannt":["Kreislaufüberlastung mit Lungenödem bei zu rascher oder zu grosser Infusionsmenge"]},"schwangerschaft":"Albumin ist ein normaler Bestandteil des menschlichen Blutes; schädliche Wirkungen sind nicht zu erwarten. Anwendung bei klarer Indikation möglich.","stillzeit":"Anwendung möglich; schädliche Wirkungen auf den Säugling sind nicht zu erwarten.","hinweise":["Wird nur im Spital unter Überwachung von Blutdruck, Puls und Flüssigkeitshaushalt gegeben.","20–25 %-Lösungen nicht mit Wasser für Injektionszwecke verdünnen – Gefahr der Hämolyse (Auflösung roter Blutkörperchen).","Nicht mit anderen Arzneimitteln, Vollblut oder Erythrozytenkonzentraten mischen.","Bei jeder Gabe werden Produktname und Chargennummer dokumentiert."],"darreichung":["Infusionslösung 4–5 % (isoonkotisch)","Infusionslösung 20–25 % (hyperonkotisch)"]},"alendronsaeure":{"wirkmechanismus":"Bremst den Knochenabbau, sodass die Knochendichte zunimmt und das Bruchrisiko sinkt. Alendronsäure lagert sich an das Knochenmineral Hydroxylapatit an und wird von den knochenabbauenden Zellen (Osteoklasten) aufgenommen. Dort hemmt sie das Enzym Farnesylpyrophosphat-Synthase, was die Aktivität der Osteoklasten unterdrückt. Da sie jahrelang im Knochen verbleibt, wirkt sie lange nach.","nebenwirkungen":{"sehrHaeufig":["Knochen-, Muskel- und Gelenkschmerzen, teils stark"],"haeufig":["Bauchschmerzen, Verdauungsbeschwerden, Verstopfung, Durchfall, Blähungen","Speiseröhrengeschwür, Schluckbeschwerden, saures Aufstossen","Kopfschmerzen, Schwindel","Haarausfall, Juckreiz","Gelenkschwellung, periphere Ödeme","Schwächegefühl"],"gelegentlich":["Übelkeit, Erbrechen, Gastritis, Entzündung der Speiseröhre","Teerstuhl (Hinweis auf Blutung)","Geschmacksstörung","Augenentzündungen (Uveitis, Skleritis)","Hautausschlag, Hautrötung","Vorübergehende grippeähnliche Beschwerden zu Behandlungsbeginn"],"selten":["Überempfindlichkeitsreaktionen mit Nesselsucht und Angioödem","Symptomatische Hypokalzämie (Calciummangel)","Verengung der Speiseröhre, Geschwüre, Blutungen oder Durchbrüche im oberen Magen-Darm-Trakt","Kiefernekrose (Absterben von Kieferknochen)","Atypische Oberschenkelbrüche","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Lichtempfindlichkeit der Haut"],"sehrSelten":["Osteonekrose des äusseren Gehörgangs"]},"schwangerschaft":"Nicht anwenden; Alendronsäure ist für Frauen nach den Wechseljahren bestimmt.","stillzeit":"Nicht anwenden.","hinweise":["Morgens nüchtern mit einem vollen Glas Leitungswasser (kein Mineralwasser, Kaffee, Saft oder Milch) unzerkaut einnehmen und mindestens 30 Minuten bis zum Frühstück und zu anderen Arzneimitteln warten.","Nach der Einnahme mindestens 30 Minuten aufrecht bleiben; nicht vor dem Schlafengehen einnehmen.","Für ausreichend Calcium und Vitamin D sorgen; vor Beginn Zahnstatus kontrollieren und auf gute Mundhygiene achten.","Bei neuen Schluckbeschwerden, Schmerzen hinter dem Brustbein oder Sodbrennen absetzen und ärztlich abklären lassen."],"darreichung":["Tabletten"]},"alfuzosin":{"wirkmechanismus":"Erleichtert das Wasserlösen, indem es die Muskulatur in Prostata, Blasenhals und Harnröhre entspannt. Alfuzosin blockiert Alpha-1-Adrenozeptoren, die im unteren Harntrakt die Spannung der glatten Muskulatur steuern; dadurch sinkt der Widerstand beim Harnabfluss, der Harnstrahl wird kräftiger und Restharn sowie Reizbeschwerden nehmen ab. Die Prostata selbst wird dabei nicht kleiner. Weil auch Alpha-1-Rezeptoren in den Blutgefässen gehemmt werden, kann der Blutdruck sinken, besonders beim Aufstehen und zu Behandlungsbeginn.","nebenwirkungen":{"haeufig":["Schwindel, Benommenheit, Drehschwindel","Kopfschmerzen","Übelkeit, Bauchschmerzen","Asthenie (Schwäche), Unwohlsein"],"gelegentlich":["Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen), v. a. zu Behandlungsbeginn","Synkope (Ohnmacht)","Herzklopfen, beschleunigter Puls","Schläfrigkeit, Sehstörungen","Schnupfen (Rhinitis)","Durchfall, Mundtrockenheit","Hautausschlag, Juckreiz","Ödeme (Wassereinlagerungen), Hitzewallungen, Brustschmerzen"],"sehrSelten":["Neu auftretende oder verstärkte Angina pectoris bei bestehender koronarer Herzkrankheit","Nesselsucht, Angioödem"],"unbekannt":["Intraoperatives Floppy-Iris-Syndrom bei Kataraktoperation","Priapismus (schmerzhafte Dauererektion)","Leberschäden, Gelbsucht","Vorhofflimmern","Neutropenie, Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen)","Erbrechen"]},"schwangerschaft":"Nicht für Frauen bestimmt.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Retardtablette jeden Tag direkt nach derselben Mahlzeit (meist dem Abendessen) unzerkaut ganz schlucken.","Vor allem zu Beginn kann Schwindel auftreten: langsam aufstehen, sich bei Schwindel hinlegen und vorsichtig sein beim Autofahren.","Vor einer Augenoperation am grauen Star oder einer Narkose die Einnahme angeben."],"darreichung":["Retardtabletten"]},"alglucosidase-alfa":{"wirkmechanismus":"Ersetzt ein Enzym, das bei Morbus Pompe fehlt, sodass sich weniger Glykogen (Speicherzucker) in den Muskelzellen ablagert. Alglucosidase alfa ist eine gentechnisch hergestellte menschliche saure Alpha-Glucosidase. Sie wird über Mannose-6-Phosphat-Rezeptoren in Herz-, Skelett- und Atemmuskulatur aufgenommen und spaltet in den Lysosomen Glykogen zu Glukose. Bei Säuglingen kann sich so die Herzmuskelverdickung zurückbilden; bei späterem Krankheitsbeginn werden Muskelkraft und Atemfunktion stabilisiert.","nebenwirkungen":{"sehrHaeufig":["Infusionsbedingte Reaktionen (z. B. Fieber, Ausschlag, Nesselsucht, Hautrötung, Herzrasen, Husten), vor allem bei Säuglingen"],"haeufig":["Kopfschmerzen, Schwindel, Kribbeln, Zittern","Übelkeit, Erbrechen, Durchfall","Juckreiz, vermehrtes Schwitzen","Blutdruckanstieg, Hitzegefühl","Engegefühl im Hals, Atemnot","Muskelkrämpfe, Muskelzucken, Muskelschmerzen","Brustbeschwerden, Müdigkeit, Schwellungen"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Herzstillstand, Herzrhythmusstörungen","Atemstillstand, Bronchospasmus (Verkrampfung der Atemwege)","Nephrotisches Syndrom und Glomerulonephritis (Nierenschädigung durch Immunreaktion)","Schwere, teils geschwürige Hautreaktionen"]},"schwangerschaft":"Nur begrenzte Erfahrungen. Anwendung nur, wenn eindeutig nötig.","stillzeit":"Geht in sehr geringen Mengen in die Muttermilch über. Stillen nur nach ärztlicher Abwägung.","hinweise":["Wird alle 2 Wochen als Infusion in eine Vene gegeben; die Infusionsgeschwindigkeit wird schrittweise gesteigert.","Infusionsreaktionen können noch Stunden nach der Infusion auftreten – Beschwerden sofort melden.","Vor jeder Narkose das Narkoseteam über Morbus Pompe und eine Herzbeteiligung informieren."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Infusionslösung"]},"alirocumab":{"wirkmechanismus":"Senkt das LDL-Cholesterin stark, indem es dafür sorgt, dass die Leber mehr «Cholesterin-Fänger» behält. Alirocumab ist ein humaner monoklonaler IgG1-Antikörper, der das im Blut zirkulierende Protein PCSK9 (Proproteinkonvertase Subtilisin/Kexin Typ 9) bindet. PCSK9 bewirkt normalerweise, dass LDL-Rezeptoren in der Leberzelle abgebaut werden; ist es blockiert, stehen mehr Rezeptoren an der Zelloberfläche zur Verfügung und entfernen LDL-Cholesterin aus dem Blut. Als Eiweiss wird Alirocumab wie körpereigene Antikörper abgebaut, nicht über Leberenzyme.","nebenwirkungen":{"haeufig":["Beschwerden der oberen Atemwege (Halsschmerzen, Schnupfen, Niesen)","Juckreiz","Reaktionen an der Injektionsstelle (Rötung, Juckreiz, Schwellung, Schmerzen)"],"selten":["Überempfindlichkeitsreaktionen, Überempfindlichkeitsvaskulitis (allergische Gefässentzündung)","Nesselsucht, nummuläres Ekzem (münzförmiger Hautausschlag)"],"unbekannt":["Angioödem (Schwellung von Gesicht, Lippen, Zunge oder Rachen)","Grippeähnliche Beschwerden"]},"schwangerschaft":"Nicht empfohlen, ausser der Zustand der Frau erfordert eine Behandlung – keine ausreichenden Erfahrungen; Antikörper gelangen vor allem im letzten Drittel zum Ungeborenen.","stillzeit":"Ein Risiko für den gestillten Säugling ist nicht auszuschliessen – ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Im Kühlschrank (2–8 °C) lagern, nicht einfrieren; vor dem Spritzen 30–40 Minuten Raumtemperatur annehmen lassen. Ausserhalb des Kühlschranks (bis 25 °C) höchstens 30 Tage haltbar.","Unter die Haut von Bauch, Oberschenkel oder Oberarm spritzen und die Stelle wechseln.","Keine bekannten Wechselwirkungen mit anderen Medikamenten; Statin und Ernährungsmassnahmen weiterführen."],"darreichung":["Injektionslösung im Fertigpen"]},"alitretinoin":{"wirkmechanismus":"Bessert Entzündung, Schuppung und Einrisse der Haut bei schwerem Handekzem. Alitretinoin (9-cis-Retinsäure) ist ein körpereigenes Vitamin-A-Derivat, das sowohl an Retinsäure-Rezeptoren (RAR) als auch an Retinoid-X-Rezeptoren (RXR) im Zellkern bindet. Es wirkt immunmodulierend und entzündungshemmend, unter anderem indem es die Bildung von Lockstoffen (Chemokinen) und die Einwanderung von Entzündungszellen in die Haut hemmt, und normalisiert die Verhornung. Der genaue Wirkmechanismus beim Handekzem ist nicht vollständig geklärt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Erhöhte Blutfette (Triglyceride, Cholesterin), vermindertes HDL-Cholesterin"],"haeufig":["Gesichtsrötung (Flush), Schwindel, Müdigkeit","Trockene Haut und Lippen, Lippenentzündung (Cheilitis), Ekzem, Haarausfall","Bindehautentzündung, trockene oder gereizte Augen","Übelkeit, Erbrechen, Mundtrockenheit","Gelenk- und Muskelschmerzen","Ohrgeräusche (Tinnitus)","Erhöhte Leberwerte und CK (Muskelenzym), Anämie (Blutarmut)","Veränderte Schilddrüsenwerte (vermindertes TSH und freies T4)"],"gelegentlich":["Verschwommenes Sehen, grauer Star (Katarakt)","Nasenbluten","Juckreiz, Hautausschlag, Hautschuppung","Knöcherne Auswüchse (Exostosen)"],"selten":["Erhöhter Hirndruck (Pseudotumor cerebri)","Gefässentzündung (Vaskulitis)"],"unbekannt":["Depression, Stimmungsschwankungen, Suizidgedanken","Entzündliche Darmerkrankungen","Verminderte Nachtsicht (Nachtblindheit)","Wassereinlagerungen (periphere Ödeme)","Überempfindlichkeitsreaktionen bis zur Anaphylaxie"]},"schwangerschaft":"Absolut kontraindiziert – Alitretinoin verursacht schwere Fehlbildungen. Frauen im gebärfähigen Alter müssen ab 1 Monat vor, während und bis 1 Monat nach der Behandlung zuverlässig verhüten und regelmässig Schwangerschaftstests machen.","stillzeit":"Kontraindiziert.","hinweise":["Einmal täglich mit einer Hauptmahlzeit einnehmen.","Während der Behandlung und bis 1 Monat danach kein Blut spenden; Kapseln nie an andere Personen weitergeben.","Blutfette und Leberwerte kontrollieren; bei Frauen im gebärfähigen Alter monatlicher Schwangerschaftstest.","Verminderte Nachtsicht möglich – Vorsicht beim Autofahren in der Dämmerung."],"darreichung":["Weichkapseln"]},"allopurinol":{"wirkmechanismus":"Senkt die Harnsäure, indem es deren Bildung im Körper bremst. Allopurinol und sein lang wirksamer Metabolit Oxipurinol hemmen das Enzym Xanthinoxidase, das Hypoxanthin und Xanthin zu Harnsäure umwandelt. Dadurch sinken die Harnsäurespiegel in Blut und Urin, und Uratablagerungen (Gichtknoten) können sich langsam auflösen. Weil die Xanthinoxidase auch Azathioprin und Mercaptopurin abbaut, steigen deren Spiegel unter Allopurinol stark an.","nebenwirkungen":{"haeufig":["Hautausschlag (bei Auftreten absetzen)","Erhöhtes TSH (Schilddrüsenwert)"],"gelegentlich":["Überempfindlichkeitsreaktionen","Übelkeit, Erbrechen, Durchfall","Erhöhte Leberwerte"],"selten":["Hepatitis bis Lebernekrose","Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse (schwere Hautreaktionen)"],"sehrSelten":["Agranulozytose, aplastische Anämie, Thrombozytopenie (schwere Blutbildstörungen)","Anaphylaxie, Angioödem","Haarausfall"],"unbekannt":["DRESS (Arzneimittelreaktion mit Fieber, Eosinophilie und Organbeteiligung)","Aseptische Meningitis (Hirnhautentzündung ohne Erreger)"]},"schwangerschaft":"Nur wenn keine sicherere Alternative besteht und der Nutzen das Risiko überwiegt; die Erfahrungen sind begrenzt.","stillzeit":"Allopurinol und Oxipurinol gehen in die Muttermilch über; in der Stillzeit nicht empfohlen.","hinweise":["Nach dem Essen mit reichlich Wasser einnehmen und täglich mindestens 2 Liter trinken.","Bei Hautausschlag, Fieber oder Schleimhautveränderungen sofort absetzen und ärztlich abklären lassen – vor allem in den ersten Behandlungsmonaten.","In den ersten Monaten können Gichtanfälle häufiger auftreten – nicht absetzen; oft wird vorbeugend Colchicin oder ein NSAR gegeben.","Kann Schwindel und Schläfrigkeit verursachen – Vorsicht beim Autofahren."],"darreichung":["Tabletten"]},"alogliptin":{"wirkmechanismus":"Verstärkt die körpereigene Blutzuckerregulation nach den Mahlzeiten. Alogliptin hemmt hochselektiv das Enzym Dipeptidylpeptidase-4 (DPP-4), das die Darmhormone GLP-1 und GIP (Inkretine) abbaut. Die höheren Inkretinspiegel steigern blutzuckerabhängig die Insulinfreisetzung und senken die Glucagonausschüttung. Alogliptin wird grösstenteils unverändert über die Nieren ausgeschieden und kaum über Cytochrom-P450-Enzyme abgebaut.","nebenwirkungen":{"haeufig":["Infektionen der oberen Atemwege, Nasen-Rachen-Entzündung","Kopfschmerzen","Bauchschmerzen","Gastroösophageale Refluxkrankheit (Sodbrennen)","Juckreiz","Hautausschlag"],"unbekannt":["Überempfindlichkeitsreaktionen einschliesslich Anaphylaxie, Angioödem und Nesselsucht","Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Leberfunktionsstörungen bis hin zum Leberversagen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, Erythema multiforme)","Interstitielle Nephritis (Nierenentzündung)","Bullöses Pemphigoid (blasenbildende Hauterkrankung)"]},"schwangerschaft":"Vorsichtshalber nicht anwenden, da keine ausreichenden Erfahrungen vorliegen; in der Schwangerschaft wird Insulin bevorzugt.","stillzeit":"Nur nach ärztlicher Abwägung; im Tierversuch geht Alogliptin in die Milch über, ein Risiko für den Säugling ist nicht auszuschliessen.","hinweise":["Einmal täglich unabhängig von den Mahlzeiten einnehmen.","Bei anhaltenden, starken Bauchschmerzen sofort ärztlich abklären lassen (mögliche Pankreatitis).","Gelbfärbung der Haut oder Augen, dunkler Urin oder Blasen auf der Haut ärztlich melden.","Vipdomet enthält zusätzlich Metformin und hat dessen Gegenanzeigen."],"darreichung":["Filmtabletten"]},"alprazolam":{"wirkmechanismus":"Wirkt rasch angstlösend und beruhigend, indem es hemmende Signale im Gehirn verstärkt. Alprazolam, ein Triazolo-Benzodiazepin, bindet an die Benzodiazepin-Bindungsstelle des GABA-A-Rezeptors und verstärkt die Wirkung des hemmenden Botenstoffs GABA (vermehrter Chlorid-Einstrom, verminderte Erregbarkeit der Nervenzellen). Es wird in der Leber fast vollständig über CYP3A4 abgebaut; die Halbwertszeit beträgt etwa 11 Stunden, bei älteren Menschen länger.","nebenwirkungen":{"sehrHaeufig":["Sedierung, Schläfrigkeit (Somnolenz)"],"haeufig":["Benommenheit, Schwindel, Kopfschmerzen","Gangunsicherheit (Ataxie), undeutliche Sprache (Dysarthrie)","Gedächtnis- und Konzentrationsstörungen","Verwirrtheit, depressive Verstimmung","Verschwommenes Sehen","Verstopfung, Übelkeit, verminderter Appetit","Müdigkeit, Reizbarkeit","Verminderte Libido, sexuelle Funktionsstörungen"],"gelegentlich":["Gedächtnislücken (Amnesie)","Paradoxe Reaktionen wie Halluzinationen, Wut, Agitiertheit","Muskelschwäche","Harninkontinenz","Zyklusstörungen","Gewichtsveränderungen","Abhängigkeit, Entzugssymptome"],"unbekannt":["Aggressivität, Feindseligkeit, Hypomanie","Leberentzündung (Hepatitis), Gelbsucht","Angioödem (Schwellung von Haut und Schleimhäuten)","Harnverhalt","Erhöhter Augeninnendruck","Missbrauch"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit, besonders im ersten Drittel. Bei Einnahme gegen Ende der Schwangerschaft oder unter der Geburt drohen beim Neugeborenen Muskelschlaffheit, Trinkschwäche, Unterkühlung, Atemprobleme und Entzugssymptome.","stillzeit":"Alprazolam geht in die Muttermilch über und kann beim Säugling Schläfrigkeit verursachen; während der Behandlung nicht stillen.","hinweise":["Kann die Fahrtüchtigkeit und das Reaktionsvermögen stark beeinträchtigen; keinen Alkohol trinken.","Grapefruitsaft meiden, da er den Alprazolam-Spiegel erhöhen kann.","Retardtabletten unzerkaut schlucken.","Nicht abrupt absetzen: besonders nach höheren Dosen drohen Entzugssymptome bis hin zu Krampfanfällen – schrittweise nach ärztlicher Anleitung reduzieren."],"darreichung":["Tabletten","Retardtabletten"]},"alprostadil":{"wirkmechanismus":"Entspannt die glatte Muskulatur von Blutgefässen und erweitert sie. Alprostadil entspricht dem körpereigenen Prostaglandin E1; es aktiviert Prostaglandin-Rezeptoren und erhöht in den Muskelzellen den cAMP-Spiegel. Beim Neugeborenen verhindert es so den natürlichen Verschluss des Ductus arteriosus, damit Lunge oder Körper bis zur Operation durchblutet bleiben. In den Schwellkörper gespritzt, erschlafft es die Schwellkörpermuskulatur und erweitert die zuführenden Arterien, sodass innert 5–20 Minuten eine Erektion entsteht.","nebenwirkungen":{"sehrHaeufig":["Penisschmerzen nach der Injektion","Apnoe (Atemstillstand) bei Neugeborenen","Fieber bei Neugeborenen","Hautrötung (Flush) bei Neugeborenen"],"haeufig":["Verlängerte Erektion (4–6 Stunden)","Bluterguss oder Blutung an der Einstichstelle","Penisfibrose (Bindegewebsverhärtung im Schwellkörper), Penisverkrümmung","Bradykardie (langsamer Puls) oder Tachykardie (Herzrasen) bei Neugeborenen","Blutdruckabfall","Durchfall bei Neugeborenen","Krampfanfälle bei Neugeborenen"],"gelegentlich":["Priapismus (schmerzhafte Dauererektion über 6 Stunden)","Schwindel, Kopfschmerzen","Hautausschlag"],"unbekannt":["Knochenveränderungen (kortikale Hyperostose) und Magenausgangsverengung bei längerer Anwendung beim Neugeborenen"]},"schwangerschaft":"Nicht zur Anwendung bei Frauen bestimmt. Ist die Partnerin schwanger oder könnte sie schwanger werden, wird beim Geschlechtsverkehr ein Kondom empfohlen.","stillzeit":"Nicht zur Anwendung bei Frauen bestimmt.","hinweise":["Erektion länger als 4 Stunden: sofort ärztliche Hilfe holen – Gefahr bleibender Schäden am Schwellkörper.","Schwellkörperinjektion höchstens einmal pro Tag und höchstens dreimal pro Woche; Einstichstelle wechseln.","Ein Kondom schützt vor der Übertragung von Krankheitserregern bei kleinen Blutungen nach der Injektion.","Beim Neugeborenen nur im Spital unter laufender Überwachung von Atmung, Herz und Blutdruck."],"darreichung":["Infusionskonzentrat","Pulver und Lösungsmittel zur Injektion in den Schwellkörper"]},"alteplase":{"wirkmechanismus":"Löst frische Blutgerinnsel auf und kann so verschlossene Gefässe wieder eröffnen. Alteplase ist ein gentechnisch hergestellter menschlicher Gewebeplasminogenaktivator (rt-PA). Er bindet an das Fibrin im Gerinnsel und wandelt dort Plasminogen in das eiweissspaltende Enzym Plasmin um, das das Fibrinnetz abbaut. Weil die Aktivierung an Fibrin gebunden viel stärker ist, wirkt Alteplase relativ gerinnselspezifisch; dennoch wird auch Fibrinogen im Blut abgebaut, was das Blutungsrisiko erklärt. Die Halbwertszeit beträgt nur wenige Minuten, darum wird es als Bolus mit anschliessender Infusion gegeben.","nebenwirkungen":{"sehrHaeufig":["Blutungen aus verletzten Gefässen und an Einstichstellen, Blutergüsse","Hirnblutung bei der Behandlung des Schlaganfalls","Beim Herzinfarkt: erneute Durchblutungsstörung oder Brustenge, tiefer Blutdruck, Herzschwäche mit Lungenödem, Rhythmusstörungen bei Wiedereröffnung des Gefässes"],"haeufig":["Blutungen im Magen-Darm-Trakt, aus Zahnfleisch, Rachen, Harn- und Geschlechtsorganen","Hirnblutung bei der Behandlung der Lungenembolie","Beim Herzinfarkt: Herzstillstand, kardiogener Schock, erneuter Infarkt"],"gelegentlich":["Hirnblutung bei der Behandlung des Herzinfarkts","Blutungen aus dem Ohr","Beim Herzinfarkt: Embolien, Herzklappenundichtigkeit, Herzbeuteltamponade"],"selten":["Überempfindlichkeitsreaktionen (Ausschlag, Nesselsucht, Bronchospasmus, Angioödem, Blutdruckabfall, Schock)","Augenblutungen","Blutungen in Herzbeutel, Leber oder Lunge","Cholesterinembolien"],"sehrSelten":["Schwere Anaphylaxie","Neurologische Störungen wie Krampfanfälle, Sprachstörungen, Verwirrtheit, Unruhe, Depression oder Psychose (meist im Zusammenhang mit Hirnblutung oder Durchblutungsstörung des Gehirns)"],"unbekannt":["Übelkeit, Erbrechen","Blutungen, die eine Bluttransfusion erfordern"]},"schwangerschaft":"Nur begrenzte Erfahrungen; bei lebensbedrohlicher Erkrankung nach Abwägung von Nutzen und Blutungsrisiko (auch für die Plazenta) anwenden.","stillzeit":"Unbekannt, ob Alteplase in die Muttermilch übergeht; Anwendung nach ärztlicher Abwägung.","hinweise":["Wird nur im Spital durch erfahrenes Personal gegeben; beim Hirnschlag zählt jede Minute – sofort Notruf 144.","Blutdruck und Neurologie werden während und nach der Infusion engmaschig überwacht.","Bei Einnahme von ACE-Hemmern auf Schwellung von Zunge, Lippen und Rachen achten.","Dem Behandlungsteam alle Blutverdünner melden, besonders Marcoumar, Sintrom, Xarelto, Eliquis, Lixiana oder Pradaxa und den Zeitpunkt der letzten Einnahme."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektions- und Infusionslösung"]},"aluminiumhydroxid-magnesiumhydroxid":{"wirkmechanismus":"Bindet überschüssige Magensäure und lindert Sodbrennen rasch. Aluminiumhydroxid und Magnesiumhydroxid reagieren mit der Salzsäure im Magen zu Salzen und Wasser und heben den pH-Wert des Mageninhalts an; dadurch wird auch das Verdauungsenzym Pepsin weniger aktiv. Aluminiumhydroxid wirkt eher verstopfend, Magnesiumhydroxid eher abführend – die Kombination gleicht diese Wirkungen teilweise aus. Aluminium bindet zudem Phosphat im Darm; nur geringe Mengen Aluminium und Magnesium werden ins Blut aufgenommen und über die Nieren ausgeschieden.","nebenwirkungen":{"gelegentlich":["Durchfall","Verstopfung"],"unbekannt":["Überempfindlichkeitsreaktionen (Juckreiz, Nesselsucht, Angioödem, Anaphylaxie)","Bauchschmerzen","Hypermagnesiämie (erhöhtes Magnesium im Blut), v. a. bei Niereninsuffizienz","Aluminium-Anreicherung bei Niereninsuffizienz mit Knochenerweichung (Osteomalazie) und Hirnschädigung (Enzephalopathie)","Phosphatmangel (Hypophosphatämie) bei langer, hochdosierter Einnahme"]},"schwangerschaft":"Kurzfristige Einnahme in üblicher Dosierung ist möglich; längere oder hochdosierte Einnahme vermeiden (Aluminiumbelastung des Kindes).","stillzeit":"In üblicher Dosierung möglich; nur geringe Mengen Aluminium und Magnesium gelangen in die Muttermilch.","hinweise":["Bei Bedarf etwa 1 Stunde nach den Mahlzeiten und vor dem Schlafengehen einnehmen; Suspension vor Gebrauch schütteln, Kautabletten gut kauen.","Zu anderen Arzneimitteln 2 Stunden Abstand halten, zu Chinolon-Antibiotika mindestens 4 Stunden.","Ohne ärztlichen Rat nicht länger als 2 Wochen einnehmen."],"darreichung":["Suspension (Gel) zum Einnehmen","Kautabletten"]},"amantadin":{"wirkmechanismus":"Verbessert die Beweglichkeit bei Parkinson, indem es das gestörte Gleichgewicht der Botenstoffe im Gehirn teilweise ausgleicht. Amantadin blockiert als nicht-kompetitiver Antagonist den NMDA-Glutamatrezeptor und dämpft so die bei Dopaminmangel überaktive glutamaterge Signalübertragung in den Basalganglien. Zusätzlich fördert es die Freisetzung von Dopamin und hemmt dessen Wiederaufnahme; ausserdem wirkt es schwach anticholinerg. Es wird unverändert über die Niere ausgeschieden.","nebenwirkungen":{"haeufig":["Schlafstörungen","Motorische und innere Unruhe","Schwindel","Übelkeit, Mundtrockenheit","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen)","Livedo reticularis (netzartige bläuliche Hautverfärbung), oft mit Knöchel- und Unterschenkelödemen","Harnverhalt bei vergrösserter Prostata"],"gelegentlich":["Verschwommenes Sehen","Psychosen mit Halluzinationen und Verfolgungsideen, v. a. bei älteren Menschen"],"sehrSelten":["Herzrhythmusstörungen: QT-Verlängerung, Torsade de pointes, Kammertachykardie und Kammerflimmern","Epileptische Krampfanfälle, Muskelzuckungen (Myoklonien)","Verminderung der weissen Blutkörperchen oder der Blutplättchen","Vorübergehender Sehverlust, erhöhte Lichtempfindlichkeit der Augen"],"unbekannt":["Hornhauttrübung und Hornhautödem","Suizidgedanken","Malignes neuroleptisches Syndrom bei abruptem Absetzen"]},"schwangerschaft":"Im Tierversuch fruchtschädigend; beim Menschen wurden Fehlbildungen (u. a. Herzfehler) berichtet. Nicht anwenden, ausser bei zwingender Notwendigkeit.","stillzeit":"Amantadin geht in die Muttermilch über. Während der Behandlung nicht stillen.","hinweise":["Letzte Tagesdosis möglichst nicht nach 16 Uhr einnehmen (Schlafstörungen).","EKG vor Beginn sowie nach 1 und 3 Wochen; bei Herzklopfen, Schwindel oder Ohnmacht sofort ärztlich abklären.","Nicht abrupt absetzen: Gefahr einer starken Verschlechterung bis zur akinetischen Krise.","Alkohol meiden; Reaktionsvermögen und Fahrtüchtigkeit können beeinträchtigt sein."],"darreichung":["Filmtabletten","Infusionslösung"]},"ambrisentan":{"wirkmechanismus":"Erweitert die Lungengefässe und entlastet so das rechte Herz. Ambrisentan blockiert selektiv den Endothelin-A-Rezeptor (ETA), über den Endothelin-1 die Gefässe verengt und das Wachstum der Gefässmuskelzellen fördert. Der ETB-Rezeptor, über den unter anderem gefässerweiternde Stoffe freigesetzt und Endothelin abgebaut wird, bleibt weitgehend unbeeinflusst. Der Widerstand in den Lungengefässen sinkt und die Belastbarkeit nimmt zu.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen (auch Nebenhöhlenkopfschmerz, Migräne)","Schwindel","Periphere Ödeme, Flüssigkeitsretention (Wassereinlagerungen)"],"haeufig":["Anämie (Blutarmut)","Herzklopfen","Verstopfte Nase, Nebenhöhlenentzündung","Atemnot, Nasenbluten","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Blutdruckabfall, Synkope (Ohnmacht), Gesichtsrötung","Herzinsuffizienz","Müdigkeit, Brustschmerzen"],"gelegentlich":["Autoimmunhepatitis, Leberschädigung, erhöhte Leberwerte"]},"schwangerschaft":"Kontraindiziert (fruchtschädigend). Schwangerschaftstest vor Beginn und monatlich; zuverlässige Verhütung während und bis 1 Monat nach der Behandlung.","stillzeit":"Kontraindiziert – nicht stillen.","hinweise":["Frauen im gebärfähigen Alter: monatlicher Schwangerschaftstest.","Hämoglobin und Leberwerte werden regelmässig kontrolliert.","Tablette unzerkaut schlucken.","Schwindel kann die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten"]},"ambroxol":{"wirkmechanismus":"Verflüssigt zähen Schleim und erleichtert das Abhusten. Ambroxol, ein Abbauprodukt von Bromhexin, steigert die Bildung von dünnflüssigem Bronchialsekret und von Surfactant und fördert die Tätigkeit der Flimmerhärchen. Zusätzlich blockiert es spannungsabhängige Natriumkanäle der Nervenendigungen; dieser örtlich betäubende Effekt lindert in Lutschtabletten Halsschmerzen.","nebenwirkungen":{"haeufig":["Geschmacksstörungen","Taubheitsgefühl in Mund und Rachen","Übelkeit"],"gelegentlich":["Erbrechen, Durchfall, Verdauungsbeschwerden, Bauchschmerzen","Mundtrockenheit"],"selten":["Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht)","Trockener Hals"],"unbekannt":["Anaphylaxie bis zum Schock, Angioödem, Juckreiz","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, akute generalisierte exanthematische Pustulose)"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen; danach nur nach ärztlicher Abwägung.","stillzeit":"Ambroxol geht in die Muttermilch über; in der Stillzeit nicht empfohlen.","hinweise":["Nicht mit Hustenstillern kombinieren.","Viel trinken unterstützt die Schleimlösung.","Bei neuem Hautausschlag oder Blasen an Haut und Schleimhäuten sofort absetzen und ärztlich abklären lassen."],"darreichung":["Sirup","Retardkapseln","Lutschtabletten"]},"amilorid":{"wirkmechanismus":"Verstärkt die Ausscheidung von Salz und Wasser leicht und verhindert, dass dabei zu viel Kalium verloren geht. Amilorid blockiert den epithelialen Natriumkanal (ENaC) im spätdistalen Tubulus und Sammelrohr der Niere, unabhängig von Aldosteron. Dadurch wird weniger Natrium zurückgewonnen und im Gegenzug weniger Kalium und Wasserstoffionen ausgeschieden. Allein wirkt Amilorid nur schwach harntreibend; es wird deshalb mit einem Thiaziddiuretikum kombiniert, dessen Kalium- und Magnesiumverlust es ausgleicht.","nebenwirkungen":{"haeufig":["Hyperkaliämie (erhöhtes Kalium)","Kopfschmerzen","Übelkeit, Appetitlosigkeit, Erbrechen","Durchfall, Bauchschmerzen","Müdigkeit, Schwächegefühl, Schwindel","Muskelkrämpfe"],"unbekannt":["Hyponatriämie (Natriummangel)","Verwirrtheit","Hautausschlag, Juckreiz","Potenzstörungen","Gelbsucht (Ikterus)","Herzrhythmusstörungen bei Hyperkaliämie"]},"schwangerschaft":"Das Kombipräparat ist in der Schwangerschaft kontraindiziert; Diuretika können die Durchblutung der Plazenta vermindern.","stillzeit":"Kontraindiziert; während der Behandlung nicht stillen.","hinweise":["Morgens mit dem Frühstück einnehmen, damit der vermehrte Harndrang nicht die Nachtruhe stört.","Kalium, Natrium und Nierenwerte regelmässig kontrollieren lassen.","Keine kaliumhaltigen Salzersatzmittel oder Kaliumpräparate ohne ärztliche Rücksprache."],"darreichung":["Tabletten"]},"amiodaron":{"wirkmechanismus":"Stabilisiert den Herzrhythmus, indem es die elektrische Erholungsphase der Herzmuskelzellen verlängert. Amiodaron blockiert vor allem Kaliumkanäle und verlängert so Aktionspotenzial und Refraktärzeit in Vorhöfen, AV-Knoten und Kammern (Klasse III). Zusätzlich hemmt es Natrium- und Calciumkanäle sowie Alpha- und Beta-Rezeptoren, was den Puls verlangsamt und die AV-Überleitung bremst. Amiodaron enthält viel Jod, reichert sich im Gewebe an und hat eine sehr lange Halbwertszeit von etwa 50 Tagen; die Wirkung hält nach dem Absetzen noch Wochen bis Monate an.","nebenwirkungen":{"sehrHaeufig":["Hornhautablagerungen im Auge (meist ohne Beschwerden, evtl. farbige Ringe um Lichtquellen)","Übelkeit, Erbrechen, Geschmacksstörungen (v. a. zu Beginn)","Lichtempfindlichkeit der Haut (Photosensibilisierung)","Erhöhte Leberwerte ohne Beschwerden"],"haeufig":["Schilddrüsenunterfunktion oder -überfunktion","Zittern, Albträume, Schlafstörungen","Mässige Bradykardie (verlangsamter Herzschlag)","Lungenschädigung (interstitielle Pneumonitis, Lungenfibrose)","Akute Leberschädigung mit Gelbsucht","Grau-bläuliche Verfärbung der Haut bei Langzeitbehandlung","Verstopfung"],"gelegentlich":["Leitungsstörungen am Herzen (SA-Block, AV-Block)","Neu auftretende oder verstärkte Herzrhythmusstörungen, teils mit Herzstillstand","Periphere Nervenschädigung (Neuropathie) und Muskelschwäche (Myopathie)","Mundtrockenheit"],"sehrSelten":["Entzündung oder Schädigung des Sehnervs (Optikusneuropathie) mit Sehverlust","Chronische Lebererkrankung bis zur Zirrhose","Akutes Lungenversagen (ARDS), v. a. nach Operationen","Bronchospasmus","Syndrom der inadäquaten ADH-Sekretion (SIADH, Natriummangel)","Ausgeprägte Bradykardie oder Sinusarrest","Blutbildstörungen (hämolytische oder aplastische Anämie, Thrombozytopenie)","Vaskulitis, Haarausfall, Nebenhodenentzündung"],"unbekannt":["Torsade de pointes","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Angioödem, Anaphylaxie","Neutropenie, Agranulozytose","Pankreatitis","Verwirrtheit, Delir, Halluzinationen, Parkinsonismus"]},"schwangerschaft":"Kontraindiziert, ausser in lebensbedrohlichen Situationen: Amiodaron und sein Jod können die Schilddrüse des Ungeborenen schädigen (Unterfunktion, Kropf) und den Herzschlag verlangsamen.","stillzeit":"Kontraindiziert: Amiodaron geht in grossen Mengen in die Muttermilch über.","hinweise":["Konsequenter Sonnenschutz (hoher Lichtschutzfaktor, Kleidung) während der Behandlung und Monate danach – sonst Sonnenbrand und bläuliche Hautverfärbung.","Regelmässige Kontrollen: EKG, Schilddrüsen- und Leberwerte, Lungenfunktion und bei Sehstörungen augenärztliche Untersuchung.","Bei neuem Husten, Atemnot oder Sehverschlechterung sofort ärztlich melden.","Kein Grapefruitsaft; jedes neue Medikament ärztlich prüfen lassen – Wechselwirkungen bestehen noch Monate nach dem Absetzen."],"darreichung":["Tabletten","Injektionslösung"]},"amisulprid":{"wirkmechanismus":"Hemmt im Gehirn gezielt bestimmte Dopamin-Rezeptoren und lindert so Wahn und Halluzinationen. Amisulprid ist ein selektiver Antagonist an Dopamin-D2- und -D3-Rezeptoren, bevorzugt im limbischen System. In niedriger Dosis blockiert es vor allem präsynaptische Rezeptoren und steigert so die Dopaminfreisetzung, was gegen Negativsymptome wirkt. Es wird kaum verstoffwechselt und hauptsächlich über die Niere ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Extrapyramidale Störungen (Zittern, Muskelsteife, Bewegungsarmut, vermehrter Speichelfluss, Sitzunruhe)"],"haeufig":["Akute Dystonie (Muskelkrämpfe, z. B. Schiefhals, Blickkrämpfe)","Schläfrigkeit","Schlaflosigkeit, Angst, Unruhe","Verstopfung, Übelkeit, Erbrechen, Mundtrockenheit","Erhöhtes Prolaktin mit Milchfluss, Ausbleiben der Regel, Brustvergrösserung, Brustschmerzen, Erektions- und Orgasmusstörungen","Gewichtszunahme","Hypotonie (tiefer Blutdruck)"],"gelegentlich":["Spätdyskinesien","Krampfanfälle","Bradykardie (langsamer Puls)","Erhöhter Blutzucker","Erhöhte Leberwerte","Leukopenie, Neutropenie","Allergische Reaktionen","Verwirrtheit"],"selten":["Malignes neuroleptisches Syndrom","QT-Verlängerung und Kammerrhythmusstörungen (Torsade de pointes), Herzstillstand, plötzlicher Herztod","Venöse Thromboembolie","Agranulozytose","Hyponatriämie (SIADH)","Gutartige Tumoren der Hirnanhangdrüse (Prolaktinom)","Osteopenie, Osteoporose"],"unbekannt":["Angioödem, Nesselsucht","Restless-Legs-Syndrom","Entzugssymptome und Bewegungsstörungen beim Neugeborenen"]},"schwangerschaft":"Begrenzte Erfahrungen. Nicht empfohlen, ausser der Nutzen überwiegt das Risiko; nach Einnahme im letzten Drittel sind beim Neugeborenen Bewegungsstörungen und Entzugssymptome möglich.","stillzeit":"Amisulprid geht in die Muttermilch über. In der Stillzeit kontraindiziert.","hinweise":["Vor Beginn EKG sowie Kalium und Magnesium kontrollieren; bei Herzklopfen oder Ohnmacht sofort ärztlich abklären.","Bei eingeschränkter Nierenfunktion wird die Dosis reduziert.","Ausbleibende Regel, Milchfluss oder sexuelle Störungen ärztlich ansprechen (Prolaktinanstieg).","Alkohol meiden; Fahrtüchtigkeit kann beeinträchtigt sein."],"darreichung":["Tabletten","Filmtabletten"]},"amitriptylin":{"wirkmechanismus":"Hellt die Stimmung auf, wirkt beruhigend und dämpft in niedriger Dosis die Schmerzweiterleitung. Amitriptylin hemmt die Wiederaufnahme von Noradrenalin und Serotonin in die Nervenzellen und verstärkt so deren Wirkung, unter anderem in den schmerzhemmenden Nervenbahnen des Rückenmarks. Daneben blockiert es Muskarin-, Histamin-H1- und Alpha-1-Rezeptoren, was Müdigkeit, Mundtrockenheit und Blutdruckabfall beim Aufstehen erklärt. Sein Abbauprodukt Nortriptylin ist ebenfalls wirksam; die antidepressive Wirkung setzt nach 2–4 Wochen ein.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit (Somnolenz), Schwindel, Zittern (Tremor), Kopfschmerzen","Mundtrockenheit, Verstopfung, Übelkeit","Herzklopfen, Herzrasen (Tachykardie)","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Sehstörungen (Akkommodationsstörungen)","Verstopfte Nase","Vermehrtes Schwitzen","Gewichtszunahme"],"haeufig":["Verwirrtheit, Unruhe (Agitiertheit), verminderte Libido","Konzentrationsstörungen, Geschmacksstörungen, Kribbeln (Parästhesien), Gangunsicherheit","Erweiterte Pupillen (Mydriasis)","AV-Block, Schenkelblock, EKG-Veränderungen (QT- und QRS-Verlängerung)","Störungen beim Wasserlassen","Erektionsstörungen","Müdigkeit, Durstgefühl","Hyponatriämie (Natriummangel)"],"gelegentlich":["Hypomanie, Manie, Angst, Schlaflosigkeit, Albträume","Krampfanfälle","Ohrgeräusche (Tinnitus)","Blutdruckanstieg","Durchfall, Erbrechen","Hautausschlag, Nesselsucht, Schwellung von Gesicht und Zunge","Harnverhalt","Leberfunktionsstörungen, Milchfluss (Galaktorrhö)"],"selten":["Knochenmarkdepression, Agranulozytose, Leukopenie, Thrombozytopenie","Delir (bei älteren Menschen), Halluzinationen","Suizidgedanken und suizidales Verhalten","Herzrhythmusstörungen","Darmlähmung (paralytischer Ileus), Speicheldrüsenschwellung","Gelbsucht (Ikterus)","Haarausfall, Lichtempfindlichkeit","Brustvergrösserung beim Mann, Fieber, Appetitverlust"],"sehrSelten":["Herzmuskelerkrankung (Kardiomyopathie), Torsade de pointes","Akutes Glaukom"],"unbekannt":["Serotoninsyndrom","Überempfindlichkeitsreaktionen, z. B. allergische Lungenentzündung (Alveolitis)","Leberentzündung (Hepatitis)","Erhöhtes Risiko für Knochenbrüche"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung. Bei Einnahme bis zur Geburt können beim Neugeborenen Entzugssymptome auftreten (Reizbarkeit, Atemprobleme, Zittern, Trinkschwäche).","stillzeit":"Amitriptylin geht in die Muttermilch über; Stillen nur nach ärztlicher Abwägung, das Kind auf Schläfrigkeit beobachten.","hinweise":["Wegen der müde machenden Wirkung meist abends einnehmen; kann die Fahrtüchtigkeit beeinträchtigen. Alkohol meiden.","Nicht abrupt absetzen (Übelkeit, Kopfschmerzen, Unwohlsein, Schlafstörungen), sondern schrittweise reduzieren.","Bei Herzerkrankungen und älteren Menschen EKG-Kontrollen; eine Überdosierung ist für das Herz lebensgefährlich – Packung sicher und für Kinder unerreichbar aufbewahren.","Gegen Mundtrockenheit auf gute Zahnpflege achten."],"darreichung":["Filmtabletten","Retardtabletten"]},"amlodipin":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Muskulatur der Blutgefässe entspannt und die Arterien weitet. Amlodipin blockiert spannungsabhängige L-Typ-Calciumkanäle vor allem in der glatten Gefässmuskulatur; weniger Calcium strömt ein, der periphere Gefässwiderstand sinkt. Bei Angina pectoris vermindert es die Nachlast und damit den Sauerstoffbedarf des Herzens und erweitert die Herzkranzgefässe. Dank der sehr langen Halbwertszeit von 35–50 Stunden genügt eine Einnahme pro Tag; die volle Wirkung baut sich über einige Tage auf.","nebenwirkungen":{"sehrHaeufig":["Ödeme (Wassereinlagerungen, vor allem Knöchelschwellungen)"],"haeufig":["Kopfschmerzen (vor allem zu Beginn), Schwindel, Schläfrigkeit","Flush (Gesichtsrötung mit Wärmegefühl)","Herzklopfen (Palpitationen)","Bauchschmerzen, Übelkeit, Verdauungsstörungen, veränderte Stuhlgewohnheiten","Sehstörungen (auch Doppeltsehen)","Atemnot","Muskelkrämpfe","Müdigkeit, Schwäche"],"gelegentlich":["Hypotonie (tiefer Blutdruck), Synkope (Ohnmacht)","Herzrhythmusstörungen (inkl. Bradykardie, Vorhofflimmern)","Schlaflosigkeit, Stimmungsschwankungen, Depression","Zittern, Kribbeln, Geschmacksstörungen, Ohrensausen","Husten, Schnupfen, Mundtrockenheit, Erbrechen","Hautausschlag, Juckreiz, Nesselsucht, Haarausfall, vermehrtes Schwitzen","Gelenk-, Muskel- und Rückenschmerzen","Vermehrter Harndrang, Erektionsstörungen, Brustvergrösserung beim Mann"],"selten":["Verwirrtheit"],"sehrSelten":["Leukopenie und Thrombozytopenie (Mangel an weissen Blutkörperchen bzw. Blutplättchen)","Herzinfarkt","Zahnfleischwucherung (Gingivahyperplasie)","Hepatitis, Gelbsucht, erhöhte Leberwerte; Pankreatitis, Gastritis","Angioödem, Erythema multiforme, Stevens-Johnson-Syndrom, exfoliative Dermatitis","Hyperglykämie (erhöhter Blutzucker), periphere Neuropathie","Lichtempfindlichkeit, Vaskulitis (Gefässentzündung)"],"unbekannt":["Extrapyramidale Störungen (Bewegungsstörungen)","Toxische epidermale Nekrolyse"]},"schwangerschaft":"Sicherheit nicht belegt; nur anwenden, wenn keine sicherere Alternative besteht und die Erkrankung ein grösseres Risiko für Mutter und Kind darstellt.","stillzeit":"Amlodipin geht in geringer Menge in die Muttermilch über; über Stillen oder Behandlung wird ärztlich entschieden.","hinweise":["Einmal täglich, unabhängig von den Mahlzeiten; die volle Blutdrucksenkung tritt erst nach einigen Tagen ein.","Grapefruit und Grapefruitsaft meiden.","Knöchelschwellungen sind häufig; bei störenden Schwellungen ärztlich besprechen statt eigenmächtig absetzen.","Schwindel, Müdigkeit oder Kopfschmerzen können besonders zu Beginn die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Tabletten"]},"amorolfin":{"wirkmechanismus":"Hemmt das Wachstum von Pilzen und tötet sie ab, indem es den Aufbau ihrer Zellmembran stört. Amorolfin blockiert in der Ergosterol-Herstellung des Pilzes zwei Enzyme (Delta-14-Reduktase und Delta-7-Delta-8-Isomerase); es fehlt Ergosterol, und unbrauchbare Sterole reichern sich in der Membran an. Es wirkt gegen Dermatophyten, Hefen und viele Schimmelpilze. Aus dem eingetrockneten Lackfilm dringt der Wirkstoff in die Nagelplatte ein und bleibt dort mehrere Tage wirksam.","nebenwirkungen":{"selten":["Nagelveränderungen wie Verfärbung, brüchige oder abbrechende Nägel"],"sehrSelten":["Brennendes Gefühl der Haut rund um den Nagel"],"unbekannt":["Allergische Reaktionen, auch am ganzen Körper","Rötung, Juckreiz, Kontaktdermatitis, Nesselsucht oder Bläschen an der Auftragsstelle"]},"schwangerschaft":"Erfahrungen fehlen: nur anwenden, wenn klar notwendig (ärztliche Abwägung). Die Aufnahme in den Körper ist sehr gering.","stillzeit":"Erfahrungen fehlen: nur nach ärztlicher Abwägung; die Aufnahme in den Körper ist sehr gering.","hinweise":["Befallene Nagelanteile vor dem Auftragen abfeilen und den Nagel entfetten; die Nagelfeile nicht für gesunde Nägel verwenden.","Ohne Unterbruch weiterbehandeln, bis der Nagel gesund nachgewachsen ist (Fingernägel etwa 6 Monate, Zehennägel 9–12 Monate).","Keine künstlichen Nägel während der Behandlung; kosmetischer Nagellack frühestens 10 Minuten nach dem Auftragen und vor der nächsten Anwendung sorgfältig entfernen.","Bei Arbeit mit Lösungsmitteln (z. B. Verdünner) undurchlässige Handschuhe tragen, damit der Lackfilm nicht abgelöst wird."],"darreichung":["Nagellack (wirkstoffhaltig)"]},"amoxicillin":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand stört. Amoxicillin hemmt die Penicillin-bindenden Proteine (Transpeptidasen), die den Zellwandbaustein Peptidoglykan quervernetzen; wachsende Bakterien gehen dadurch zugrunde (bakterizide Wirkung). Es wirkt gegen Streptokokken, Pneumokokken, Enterokokken und einen Teil der gramnegativen Keime wie Haemophilus influenzae und E. coli. Bakterien, die Beta-Laktamasen bilden (z. B. die meisten Staphylokokken), zerstören Amoxicillin – dafür gibt es die Kombination mit Clavulansäure.","nebenwirkungen":{"haeufig":["Durchfall","Übelkeit","Hautausschlag"],"gelegentlich":["Erbrechen","Nesselsucht (Urtikaria), Juckreiz"],"sehrSelten":["Pilzinfektionen von Haut und Schleimhäuten (Candidose)","Blutbildveränderungen (Leukopenie bis Agranulozytose, Thrombozytopenie, hämolytische Anämie)","Schwere allergische Reaktionen (Anaphylaxie, Angioödem, Serumkrankheit, allergische Gefässentzündung)","Krampfanfälle, Schwindel, Überaktivität","Antibiotika-assoziierte Kolitis (schwere Darmentzündung), schwarze Haarzunge","Leberentzündung, Gelbsucht durch Gallestau","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP, DRESS)","Interstitielle Nephritis (Nierenentzündung), Kristalle im Urin"],"unbekannt":["Jarisch-Herxheimer-Reaktion","Aseptische Meningitis (nicht bakterielle Hirnhautentzündung)","Kounis-Syndrom (allergisch ausgelöster Herzinfarkt)","Arzneimittelinduziertes Enterokolitis-Syndrom (wiederholtes Erbrechen 1–4 Stunden nach Einnahme, vor allem bei Kindern)"]},"schwangerschaft":"Kann angewendet werden, wenn eine Antibiotikabehandlung nötig ist; langjährige Erfahrung ohne Hinweise auf eine Schädigung des Kindes.","stillzeit":"Erlaubt. Geht in kleinen Mengen in die Muttermilch über; beim Säugling sind Durchfall oder Pilzbefall möglich.","hinweise":["Kann unabhängig von den Mahlzeiten eingenommen werden; die verordnete Behandlungsdauer einhalten, auch wenn es schon besser geht.","Bei Hautausschlag, Atemnot oder Schwellungen sofort ärztlichen Rat einholen; eine bestätigte Allergie im Allergiepass vermerken.","Bei hoher Dosierung reichlich trinken.","Schwerer oder blutiger Durchfall, auch Wochen nach der Behandlung, muss ärztlich abgeklärt werden."],"darreichung":["Filmtabletten","Dispergierbare Tabletten","Pulver für Suspension zum Einnehmen (Sirup)"]},"amoxicillin-clavulansaeure":{"wirkmechanismus":"Tötet Bakterien ab und schützt das Antibiotikum vor bakteriellen Abwehrenzymen. Amoxicillin hemmt die Penicillin-bindenden Proteine und damit den Aufbau der bakteriellen Zellwand (bakterizide Wirkung). Clavulansäure hat selbst kaum antibakterielle Wirkung, blockiert aber irreversibel viele Beta-Laktamasen, mit denen Bakterien Amoxicillin sonst zerstören würden. Dadurch wirkt die Kombination zusätzlich gegen Beta-Laktamase-bildende Staphylokokken (nicht MRSA), Haemophilus influenzae, Moraxella catarrhalis, viele E.-coli-Stämme und Anaerobier.","nebenwirkungen":{"sehrHaeufig":["Durchfall (bei Erwachsenen)"],"haeufig":["Übelkeit (vor allem bei hohen Dosen)","Erbrechen","Pilzinfektionen von Haut und Schleimhäuten (z. B. Mund- oder Scheidenpilz)"],"gelegentlich":["Schwindel, Kopfschmerzen","Verdauungsbeschwerden","Anstieg der Leberwerte (AST/ALT)","Hautausschlag, Juckreiz, Nesselsucht"],"selten":["Vorübergehende Leukopenie, Neutropenie oder Thrombozytopenie","Erythema multiforme (Hautausschlag mit kokardenförmigen Flecken)"],"unbekannt":["Leberentzündung und Gelbsucht durch Gallestau (kann schwer sein, auch noch Wochen nach Behandlungsende)","Anaphylaxie, Angioödem, serumkrankheitsähnliche Reaktion, allergische Gefässentzündung","Agranulozytose, hämolytische Anämie, verlängerte Blutungs- und Gerinnungszeit","Krampfanfälle, Überaktivität, aseptische Meningitis","Antibiotika-assoziierte Kolitis (schwere Darmentzündung), schwarze Haarzunge","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP, DRESS)","Interstitielle Nephritis (Nierenentzündung), Kristalle im Urin","Arzneimittelinduziertes Enterokolitis-Syndrom, Kounis-Syndrom (allergisch ausgelöster Herzinfarkt)"]},"schwangerschaft":"Nach ärztlicher Abwägung möglich. Bei vorzeitigem Blasensprung vor dem Geburtstermin nicht anwenden: Hinweise auf ein erhöhtes Risiko einer schweren Darmentzündung (nekrotisierende Enterokolitis) beim Neugeborenen.","stillzeit":"Erlaubt; beide Wirkstoffe gehen in geringen Mengen in die Muttermilch über (beim Säugling Durchfall oder Pilzbefall möglich).","hinweise":["Zu Beginn einer Mahlzeit einnehmen – so wird es besser vertragen und die Clavulansäure besser aufgenommen.","Die Behandlung soll ohne ärztliche Überprüfung nicht länger als 14 Tage dauern.","Gelbe Haut oder Augen, dunkler Urin oder heller Stuhl – auch Wochen nach Behandlungsende – sofort ärztlich abklären lassen.","Präparate verschiedener Stärken sind nicht beliebig austauschbar, weil sie unterschiedlich viel Clavulansäure enthalten."],"darreichung":["Filmtabletten","Dispergierbare Tabletten","Pulver für Suspension zum Einnehmen (Sirup)","Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"amphotericin-b":{"wirkmechanismus":"Tötet Pilze ab, indem es Löcher in ihre Zellmembran reisst. Amphotericin B bindet an Ergosterol der Pilzmembran und bildet Poren, durch die Ionen und Zellbestandteile austreten; es wirkt so gegen ein breites Spektrum von Hefen und Schimmelpilzen sowie gegen Leishmanien. Eine schwächere Bindung an das Cholesterin menschlicher Zellen erklärt Nierenschäden und Infusionsreaktionen; die Verpackung in Liposomen (AmBisome) vermindert diese Giftigkeit deutlich. Zum Einnehmen wird Amphotericin B praktisch nicht aufgenommen und wirkt nur örtlich in Mund und Darm.","nebenwirkungen":{"sehrHaeufig":["Hypokaliämie (Kaliummangel)","Übelkeit, Erbrechen","Fieber, Schüttelfrost (Infusionsreaktion)"],"haeufig":["Hyponatriämie, Hypokalzämie, Hypomagnesiämie (Salzmangel im Blut), erhöhter Blutzucker","Kopfschmerzen","Herzrasen, Blutdruckabfall, Hitzegefühl (Flush)","Atemnot","Durchfall, Bauchschmerzen","Erhöhte Leber- und Nierenwerte (Kreatinin, Harnstoff)","Hautausschlag","Rücken- und Brustschmerzen"],"gelegentlich":["Thrombozytopenie (Mangel an Blutplättchen)","Anaphylaktoide Reaktionen","Krampfanfälle","Bronchospasmus (Verkrampfung der Atemwege)"],"unbekannt":["Anaphylaxie, Angioödem","Herzrhythmusstörungen bis Herzstillstand","Akutes Nierenversagen","Rhabdomyolyse (Muskelzerfall)","Anämie (Blutarmut)","Bei Einnahme (Suspension, Lutschtabletten): Übelkeit, Durchfall, Reizung der Mundschleimhaut, allergische Hautreaktionen"]},"schwangerschaft":"Die Infusion nur bei zwingender Notwendigkeit, wenn der Nutzen das mögliche Risiko überwiegt. Präparate zum Einnehmen werden kaum aufgenommen; Anwendung nach ärztlicher Abwägung.","stillzeit":"Ob Amphotericin B nach Infusion in die Muttermilch übergeht, ist nicht bekannt; über Abstillen oder Therapieverzicht ärztlich entscheiden.","hinweise":["Liposomales (AmBisome) und herkömmliches Amphotericin B sind nicht austauschbar – die Dosierungen unterscheiden sich stark; Verwechslungen können tödlich sein.","Während der Infusionstherapie Nierenwerte, Kalium, Magnesium und Blutbild regelmässig kontrollieren.","Suspension oder Lutschtabletten nach dem Essen anwenden und möglichst lange im Mund lassen."],"darreichung":["Pulver zur Herstellung einer Infusionslösung (liposomal)","Suspension zum Einnehmen","Lutschtabletten"]},"amylmetacresol-dichlorbenzylalkohol":{"wirkmechanismus":"Wirkt örtlich desinfizierend und lindert Halsschmerzen. Amylmetacresol und Dichlorbenzylalkohol sind Antiseptika, die Bakterien und manche Viren in Mund und Rachen abtöten, indem sie deren Eiweisse und Zellmembranen schädigen. Amylmetacresol blockiert zudem Natriumkanäle an Nervenendigungen und wirkt dadurch leicht schmerzlindernd. Beim Lutschen wird vermehrt Speichel gebildet, der die Schleimhaut befeuchtet.","nebenwirkungen":{"unbekannt":["Überempfindlichkeitsreaktionen (Ausschlag, Schwellungen)","Brennen oder Missempfindungen im Mund, Zungenbrennen","Magenbeschwerden, Übelkeit"]},"schwangerschaft":"Die Sicherheit ist nicht belegt, ein Risiko wird aber nicht erwartet; nur nach Rücksprache mit Ärztin, Arzt oder Apotheke anwenden.","stillzeit":"Nur nach Rücksprache mit Ärztin, Arzt oder Apotheke anwenden.","hinweise":["Langsam im Mund zergehen lassen, nicht zerkauen oder ganz schlucken.","Ohne ärztlichen Rat nur wenige Tage anwenden; bei eitrigem Belag, hohem Fieber oder Atemnot ärztlich abklären lassen.","Die in der Packungsbeilage genannte Höchstzahl an Lutschtabletten pro Tag nicht überschreiten."],"darreichung":["Lutschtabletten"]},"anastrozol":{"wirkmechanismus":"Senkt den Östrogenspiegel nach den Wechseljahren stark, sodass hormonabhängige Tumoren nicht mehr angeregt werden. Nach der Menopause entsteht Östrogen vor allem im Fettgewebe aus Androgenen durch das Enzym Aromatase. Anastrozol hemmt die Aromatase selektiv und reversibel und senkt das Östradiol um rund 80 %. Bei Frauen vor der Menopause genügt das nicht, weil die Eierstöcke weiter Östrogen bilden.","nebenwirkungen":{"sehrHaeufig":["Hitzewallungen","Kopfschmerzen","Gelenkschmerzen und Gelenksteifigkeit","Arthritis","Übelkeit","Hautausschlag","Schwäche"],"haeufig":["Knochenschmerzen, Muskelschmerzen","Karpaltunnelsyndrom (Taubheit in den Fingern)","Haarausfall","Scheidentrockenheit, Scheidenblutungen","Durchfall, Erbrechen, Appetitlosigkeit","Erhöhtes Cholesterin","Schläfrigkeit, Geschmacksstörungen","Erhöhte Leberwerte"],"gelegentlich":["Schnellender Finger","Hyperkalzämie","Nesselsucht","Hepatitis"],"selten":["Erythema multiforme (Hautreaktion)","Anaphylaxie, Angioödem","Hautgefässentzündung (kutane Vaskulitis)"],"sehrSelten":["Stevens-Johnson-Syndrom"],"unbekannt":["Abnahme der Knochendichte, Osteoporose"]},"schwangerschaft":"Kontraindiziert.","stillzeit":"Kontraindiziert.","hinweise":["Täglich zur gleichen Zeit einnehmen, meist über 5 Jahre oder länger.","Knochendichte regelmässig messen; ausreichend Calcium, Vitamin D und Bewegung.","Gelenkschmerzen sind häufig – vor einem Abbruch mit der Ärztin oder dem Arzt sprechen."],"darreichung":["Filmtabletten"]},"anti-d-immunglobulin":{"wirkmechanismus":"Verhindert, dass das Immunsystem einer Rhesus-negativen Mutter Antikörper gegen rhesus-positive Blutzellen des Kindes bildet. Das Präparat enthält Antikörper gegen das Rhesus-D-Antigen aus Spenderplasma. Sie binden an rhesus-positive rote Blutkörperchen, die in den mütterlichen Kreislauf gelangt sind, und sorgen für deren raschen Abbau, bevor das Immunsystem darauf reagiert. So wird in einer späteren Schwangerschaft eine Blutzerstörung beim Kind (Morbus haemolyticus neonatorum) verhindert.","nebenwirkungen":{"gelegentlich":["Kopfschmerzen","Fieber, Schüttelfrost, Unwohlsein","Hautreaktionen, Rötung, Juckreiz","Übelkeit","Schmerzen und Reaktionen an der Injektionsstelle"],"selten":["Überempfindlichkeitsreaktionen bis zur Anaphylaxie (schwere allergische Reaktion)","Herzrasen, Blutdruckabfall","Atemnot","Gelenkschmerzen"],"unbekannt":["Hämolyse (Blutzerfall), v. a. nach intravenöser Gabe bei Fehltransfusion","Nierenversagen nach massiver Hämolyse"]},"schwangerschaft":"Für die Anwendung in der Schwangerschaft vorgesehen; keine schädlichen Wirkungen auf das Kind bekannt.","stillzeit":"Kann in der Stillzeit angewendet werden; Immunglobuline gehen in die Muttermilch über, ohne den Säugling zu gefährden.","hinweise":["Nach der Geburt möglichst innert 72 Stunden verabreichen; auch später ist die Gabe noch sinnvoll.","Vor allfälligen Lebendimpfungen die Anti-D-Gabe angeben.","Nach der Gabe kann ein Antikörpersuchtest wochenlang positiv ausfallen."],"darreichung":["Fertigspritze (Injektionslösung, intramuskulär oder intravenös)"]},"antithrombin-human":{"wirkmechanismus":"Ersetzt ein körpereigenes Eiweiss, das die Blutgerinnung bremst und so Blutgerinnsel verhindert. Antithrombin ist der wichtigste natürliche Hemmstoff der Gerinnung: Es inaktiviert Thrombin (Faktor IIa) und Faktor Xa sowie in geringerem Mass weitere aktivierte Gerinnungsfaktoren (IXa, XIa, XIIa). Heparin beschleunigt diese Hemmung um ein Vielfaches; umgekehrt wirkt Heparin bei Antithrombinmangel schlecht. Die Gabe hebt die Antithrombin-Aktivität im Blut wieder in den Normalbereich.","nebenwirkungen":{"selten":["Überempfindlichkeitsreaktionen (Hautrötung, Nesselsucht, Juckreiz, Übelkeit, Blutdruckabfall)","Anaphylaxie bis zum Schock"],"unbekannt":["Fieber"]},"schwangerschaft":"Nur bei klarer Notwendigkeit; bei angeborenem Antithrombinmangel kann die Behandlung rund um Schwangerschaft und Geburt wichtig sein, um Thrombosen zu verhindern.","stillzeit":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung.","hinweise":["Wird von Fachpersonen in eine Vene gespritzt oder infundiert; die Antithrombin-Aktivität im Blut wird kontrolliert.","Bei gleichzeitiger Heparingabe engmaschige Gerinnungskontrollen.","Produktname und Chargennummer werden dokumentiert (Rückverfolgbarkeit von Plasmaprodukten)."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektions- oder Infusionslösung"]},"apixaban":{"wirkmechanismus":"Hemmt die Blutgerinnung, indem es einen zentralen Gerinnungsfaktor direkt blockiert. Apixaban bindet direkt, selektiv und reversibel an den Gerinnungsfaktor Xa, frei im Blut und im Gerinnsel, ohne Antithrombin zu benötigen. Dadurch wird weniger Thrombin gebildet und neue Gerinnsel entstehen nicht. Apixaban wird über mehrere Wege ausgeschieden (u. a. Abbau über CYP3A4, Transport durch P-Glykoprotein, nur etwa ein Viertel über die Nieren); als Gegenmittel steht Andexanet alfa zur Verfügung.","nebenwirkungen":{"haeufig":["Anämie (Blutarmut)","Blutungen und Blutergüsse (Hämatome)","Nasenbluten","Magen-Darm-Blutungen","Übelkeit","Blut im Urin","Erhöhte GGT (Leberwert)"],"gelegentlich":["Hirnblutung","Thrombozytopenie (verminderte Blutplättchen)","Überempfindlichkeit, allergisches Ödem, Anaphylaxie, Juckreiz","Blutungen aus Enddarm, Hämorrhoiden und Mund; Bluthusten; Blutungen im Bauchraum","Ungewöhnliche Scheidenblutungen","Erhöhte Leberwerte und erhöhtes Bilirubin","Hautausschlag, Haarausfall"],"selten":["Blutungen der Atemwege und im hinteren Bauchraum (retroperitoneal)","Muskelblutungen"],"unbekannt":["Erythema multiforme (Hautreaktion), Entzündung kleiner Hautgefässe (kutane Vaskulitis)","Antikoagulanzien-assoziierte Nephropathie (Nierenschädigung durch Blutungen in der Niere)"]},"schwangerschaft":"Keine ausreichenden Daten; vorsichtshalber während der Schwangerschaft nicht anwenden.","stillzeit":"Unbekannt, ob Apixaban in die Muttermilch übergeht; entweder abstillen oder auf Apixaban verzichten.","hinweise":["Regelmässig zweimal täglich im Abstand von etwa 12 Stunden einnehmen, mit oder ohne Essen; Tabletten dürfen zerstossen werden.","Nicht eigenmächtig absetzen – Gefahr von Schlaganfall oder Thrombose.","Vor Operationen, Zahnbehandlungen und neuen Medikamenten Arzt oder Apotheke informieren; Nierenfunktion regelmässig kontrollieren.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, starke Kopfschmerzen, ungewöhnliche Blutergüsse) sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"aprepitant":{"wirkmechanismus":"Unterdrückt vor allem den verzögerten Brechreiz, der in den Tagen nach einer Chemotherapie auftritt. Aprepitant blockiert im Gehirn selektiv die Neurokinin-1-(NK1-)Rezeptoren, an denen der Botenstoff Substanz P Erbrechen auslöst. Es ergänzt damit die Wirkung von 5-HT3-Antagonisten (Setronen) und Dexamethason. Aprepitant wird über CYP3A4 abgebaut, hemmt dieses Enzym während der 3-tägigen Behandlung mässig und induziert danach CYP3A4 und CYP2C9 für einige Wochen.","nebenwirkungen":{"haeufig":["Schluckauf","Müdigkeit (Fatigue)","Appetitlosigkeit","Obstipation (Verstopfung)","Dyspepsie (Verdauungsbeschwerden)","Kopfschmerzen","Erhöhte Leberwerte (ALT)"],"gelegentlich":["Schwindel, Schläfrigkeit, Angst","Bauchschmerzen, Aufstossen, Mundtrockenheit, Blähungen, Übelkeit","Herzklopfen, Hitzewallungen","Hautausschlag, Akne","Schmerzen beim Wasserlassen","Febrile Neutropenie, Anämie (Blutarmut)"],"selten":["Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)","Langsamer Puls (Bradykardie)"],"unbekannt":["Überempfindlichkeitsreaktionen bis zur Anaphylaxie","Angioödem, Nesselsucht, Juckreiz"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn es klar notwendig ist. Hormonelle Verhütung kann während und bis 2 Monate nach der Einnahme unzuverlässig sein.","stillzeit":"Nicht bekannt, ob Aprepitant in die Muttermilch übergeht; Stillen während der Behandlung wird nicht empfohlen.","hinweise":["Üblicherweise 3 Tage: 1 Stunde vor der Chemotherapie am Tag 1, dann je morgens an Tag 2 und 3; mit oder ohne Essen.","Bis 2 Monate nach der letzten Dosis zusätzlich nicht hormonell verhüten (z. B. Kondom).","Wer Phenprocoumon oder einen anderen Vitamin-K-Antagonisten nimmt: INR in den Wochen danach kontrollieren lassen.","Alle anderen Medikamente angeben – Aprepitant verändert die Spiegel vieler Arzneimittel."],"darreichung":["Kapseln"]},"aprocitentan":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Wirkung des stark gefässverengenden Botenstoffs Endothelin-1 blockiert. Aprocitentan hemmt beide Endothelin-Rezeptoren (ETA und ETB) und greift damit an einem anderen Signalweg an als die übrigen Blutdrucksenker. Endothelin-1 fördert Gefässverengung, Salz- und Wasserrückhaltung sowie Umbauprozesse in Gefässen und Organen. Aprocitentan ist der aktive Metabolit von Macitentan.","nebenwirkungen":{"sehrHaeufig":["Ödeme, Flüssigkeitsretention (Wassereinlagerungen)"],"haeufig":["Anämie (Abfall des Hämoglobins)"],"unbekannt":["Leberwerterhöhungen","Verschlechterung einer Herzinsuffizienz durch Flüssigkeitseinlagerung"]},"schwangerschaft":"Kontraindiziert – fruchtschädigend wie andere Endothelin-Antagonisten. Vor Beginn Schwangerschaft ausschliessen; zuverlässige Verhütung während und bis 1 Monat nach der Behandlung.","stillzeit":"Kontraindiziert – nicht stillen.","hinweise":["Bei raschem Gewichtsanstieg, geschwollenen Beinen oder Atemnot ärztlich abklären lassen.","Hämoglobin und Leberwerte werden regelmässig kontrolliert.","Frauen im gebärfähigen Alter: zuverlässig verhüten und Schwangerschaftstests nach ärztlicher Anweisung machen."],"darreichung":["Filmtabletten"]},"aripiprazol":{"wirkmechanismus":"Stabilisiert die Signalübertragung durch Dopamin im Gehirn: Es dämpft sie, wo sie überaktiv ist, und stützt sie, wo sie zu schwach ist. Aripiprazol ist ein Partialagonist an Dopamin-D2- und -D3- sowie Serotonin-5-HT1A-Rezeptoren und ein Antagonist an 5-HT2A-Rezeptoren. Es hat nur geringe Affinität zu Histamin- und Muskarinrezeptoren, daher weniger Müdigkeit und Gewichtszunahme. Abgebaut wird es über CYP2D6 und CYP3A4.","nebenwirkungen":{"haeufig":["Sitzunruhe (Akathisie), extrapyramidale Störungen, Zittern","Schlaflosigkeit, Unruhe, Angst","Kopfschmerzen, Schwindel, Schläfrigkeit, Sedierung","Verschwommenes Sehen","Übelkeit, Erbrechen, Verstopfung, Verdauungsbeschwerden","Vermehrter Speichelfluss","Müdigkeit"],"gelegentlich":["Erhöhter Blutzucker","Erhöhtes oder erniedrigtes Prolaktin","Depression, gesteigertes sexuelles Verlangen","Spätdyskinesien, Dystonie, Restless-Legs-Syndrom","Doppelbilder, Lichtempfindlichkeit der Augen","Herzrasen","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen)","Schluckauf"],"unbekannt":["Impulskontrollstörungen (Spielsucht, Kaufsucht, Essattacken, gesteigertes sexuelles Verlangen)","Suizidgedanken und Suizidversuche, Aggression","Malignes neuroleptisches Syndrom, Serotoninsyndrom, Krampfanfälle","QT-Verlängerung, Kammerrhythmusstörungen (Torsade de pointes), plötzlicher Herztod","Verminderung der weissen Blutkörperchen oder der Blutplättchen","Venöse Thromboembolie","Diabetische Ketoazidose, Hyponatriämie","Pankreatitis, Hepatitis, Leberversagen, Rhabdomyolyse (Muskelzerfall)"]},"schwangerschaft":"Begrenzte Erfahrungen; nur anwenden, wenn der Nutzen das Risiko klar überwiegt. Nach Einnahme im letzten Drittel sind beim Neugeborenen Bewegungsstörungen und Entzugssymptome möglich.","stillzeit":"Aripiprazol geht in die Muttermilch über. Nur nach ärztlicher Abwägung stillen, sonst abstillen.","hinweise":["Angehörige sollten auf Spielsucht, Kaufsucht, Essattacken oder auffälliges Sexualverhalten achten und dies ärztlich melden.","Überhitzung und Flüssigkeitsmangel vermeiden (die Temperaturregulation kann gestört sein).","Abilify Maintena wird monatlich gespritzt; nach der ersten Injektion werden meist noch 14 Tage Tabletten eingenommen.","Fahrtüchtigkeit kann beeinträchtigt sein; Alkohol meiden."],"darreichung":["Tabletten","Schmelztabletten","Depot-Injektionssuspension"]},"artemether-lumefantrin":{"wirkmechanismus":"Tötet Malariaerreger in den roten Blutkörperchen ab. Beide Wirkstoffe stören im Parasiten die Entgiftung des Häms, das beim Abbau von Hämoglobin entsteht. Artemether und sein aktiver Metabolit Dihydroartemisinin bilden über ihre Endoperoxidbrücke reaktive Radikale und senken die Parasitenzahl sehr rasch; das lang wirksame Lumefantrin beseitigt die verbleibenden Erreger und verhindert Rückfälle. Gegen ruhende Leberformen von P. vivax und P. ovale wirkt die Kombination nicht.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen, Schwindel","Appetitlosigkeit","Bauchschmerzen","Schlafstörungen","Herzklopfen (Palpitationen)","Gelenk- und Muskelschmerzen","Schwäche, Müdigkeit"],"haeufig":["Übelkeit, Erbrechen, Durchfall","QT-Verlängerung im EKG","Hautausschlag, Juckreiz","Husten","Missempfindungen (Parästhesien), unwillkürliche Muskelzuckungen","Gangstörungen"],"gelegentlich":["Schläfrigkeit","Nesselsucht","Koordinationsstörungen (Ataxie), verminderte Hautempfindung","Erhöhte Leberwerte"],"unbekannt":["Überempfindlichkeitsreaktionen, Angioödem"]},"schwangerschaft":"Im ersten Schwangerschaftsdrittel nur, wenn keine andere geeignete Malariabehandlung verfügbar ist; im zweiten und dritten Drittel nach ärztlicher Abwägung.","stillzeit":"Während der Behandlung und bis mindestens eine Woche nach der letzten Dosis nicht stillen (lange Halbwertszeit von Lumefantrin).","hinweise":["Jede Dosis mit einer fetthaltigen Mahlzeit oder Milch einnehmen – sonst wird Lumefantrin schlecht aufgenommen.","Alle 6 Dosen über 3 Tage vollständig einnehmen; bei Erbrechen innerhalb einer Stunde die Dosis wiederholen.","Nicht zur Malariavorbeugung geeignet. Als Notfall-Selbstbehandlung auf Reisen nur nach ärztlicher Beratung und danach trotzdem rasch ärztliche Kontrolle.","Bei Schwindel oder Müdigkeit nicht Auto fahren."],"darreichung":["Tabletten"]},"ascorbinsaeure-vitamin-c":{"wirkmechanismus":"Ersetzt Vitamin C, das der Mensch nicht selbst bilden kann. Ascorbinsäure ist ein wasserlösliches Antioxidans und Cofaktor von Enzymen, die unter anderem Kollagen für Bindegewebe, Gefässe, Haut und Wundheilung sowie Carnitin und Noradrenalin bilden. Zudem verbessert es die Aufnahme von Eisen aus pflanzlicher Nahrung. Ein schwerer Mangel führt zu Skorbut mit Zahnfleischbluten, Blutergüssen und Wundheilungsstörungen; Überschüsse werden rasch über die Niere ausgeschieden.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden wie Durchfall, Übelkeit, Bauchkrämpfe (vor allem bei Dosen über 1 g pro Tag)","Oxalat-Nierensteine bei hohen Dosen","Hämolyse (Blutzerfall) bei G6PD-Mangel","Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz)"]},"schwangerschaft":"In üblichen Dosen erlaubt; sehr hohe Dosen meiden.","stillzeit":"In üblichen Dosen erlaubt; Vitamin C geht in die Muttermilch über.","hinweise":["Kann Laborwerte verfälschen (z. B. Blutzuckermessung mit bestimmten Geräten, Tests auf Blut oder Zucker im Urin und Stuhl) – vor Untersuchungen angeben.","Brausetabletten in einem Glas Wasser auflösen; hohe Dosen auf mehrere Einnahmen verteilen.","Bei Einnahme hoher Dosen reichlich trinken (Vorbeugung von Nierensteinen)."],"darreichung":["Brausetabletten","Kautabletten"]},"asfotase-alfa":{"wirkmechanismus":"Ersetzt ein Enzym, das für den Einbau von Mineralstoffen in die Knochen nötig ist. Asfotase alfa ist ein gentechnisch hergestelltes Fusionseiweiss aus gewebeunspezifischer alkalischer Phosphatase, einem Antikörper-Fc-Teil und einem knochenbindenden Abschnitt aus zehn Asparaginsäuren. Es spaltet anorganisches Pyrophosphat, das die Mineralisierung hemmt, sowie Pyridoxal-5'-phosphat. So können Calcium und Phosphat wieder als Hydroxylapatit in die Knochen eingebaut werden.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Einstichstelle (Rötung, Verfärbung, Schmerz, Juckreiz, Schwellung, Bluterguss, Verhärtung, Fettgewebsveränderungen)","Kopfschmerzen","Gliederschmerzen"],"haeufig":["Überempfindlichkeitsreaktionen","Hautinfektion an der Einstichstelle (Zellulitis)","Neigung zu Blutergüssen","Hitzewallungen","Hypokalzämie (tiefes Calcium im Blut)","Nierensteine","Muskelschmerzen","Schüttelfrost, Fieber"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Keine Erfahrungen. Anwendung nicht empfohlen, ausser wenn die Behandlung eindeutig nötig ist.","stillzeit":"Nicht bekannt, ob Asfotase alfa in die Muttermilch übergeht. Entscheid über Stillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Wird mehrmals pro Woche unter die Haut gespritzt; Einstichstellen regelmässig wechseln und nicht in gerötete, verhärtete oder geschwollene Stellen spritzen (Fettgewebsveränderungen).","Im Kühlschrank lagern (2–8 °C), nicht einfrieren; angebrochene Durchstechflaschen nicht aufbewahren.","Kann Labortests verfälschen, die alkalische Phosphatase verwenden – Labor über die Behandlung informieren.","Augen, Nieren, Calcium und Parathormon werden regelmässig kontrolliert; die Dosis wird dem Körpergewicht angepasst."],"darreichung":["Injektionslösung zur Anwendung unter die Haut"]},"atenolol":{"wirkmechanismus":"Verlangsamt den Herzschlag und senkt den Blutdruck, indem es die Wirkung der Stresshormone am Herzen blockiert. Atenolol hemmt bevorzugt die Beta-1-Rezeptoren des Herzens und vermindert so Herzfrequenz, Kontraktionskraft und Sauerstoffbedarf. Es ist wasserlöslich, gelangt kaum ins Gehirn, wird praktisch nicht in der Leber abgebaut und unverändert über die Niere ausgeschieden.","nebenwirkungen":{"haeufig":["Bradykardie (langsamer Puls)","Kalte Hände und Füsse","Müdigkeit","Magen-Darm-Beschwerden (Übelkeit, Durchfall, Verstopfung)"],"gelegentlich":["Schlafstörungen","Erhöhte Leberwerte"],"selten":["Verschlechterung einer Herzinsuffizienz, AV-Block","Schwindel, Kopfschmerzen, Kribbeln","Stimmungsschwankungen, Albträume, Verwirrtheit, Depression","Bronchospasmus bei Asthma","Thrombozytopenie (Mangel an Blutplättchen), Purpura","Hautausschlag, Verschlechterung einer Psoriasis, Haarausfall","Sehstörungen, trockene Augen","Erektionsstörungen","Leberschädigung mit Gallenstau"],"sehrSelten":["Erhöhte antinukleäre Antikörper (ANA)"],"unbekannt":["Lupus-ähnliches Krankheitsbild"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung: Atenolol geht auf das Kind über und wurde mit Wachstumsverzögerung in Verbindung gebracht. Das Neugeborene auf langsamen Puls und Unterzuckerung überwachen.","stillzeit":"Atenolol reichert sich in der Muttermilch an; Stillen wird nicht empfohlen bzw. nur unter Beobachtung des Säuglings (langsamer Puls, Unterzuckerung).","hinweise":["Nicht abrupt absetzen – über 1–2 Wochen ausschleichen.","Bei eingeschränkter Nierenfunktion ist eine tiefere Dosis nötig.","Schwindel und Müdigkeit können die Fahrtüchtigkeit beeinträchtigen, besonders zu Beginn und mit Alkohol."],"darreichung":["Tabletten","Filmtabletten"]},"atezolizumab":{"wirkmechanismus":"Hilft dem eigenen Immunsystem, Krebszellen zu erkennen und zu bekämpfen. Atezolizumab ist ein humanisierter monoklonaler Antikörper, der an PD-L1 auf Tumor- und Immunzellen bindet. Dadurch wird die Bindung von PD-L1 an die Rezeptoren PD-1 und B7.1 auf T-Zellen verhindert, die sonst die T-Zell-Aktivität bremst. Die reaktivierten T-Zellen greifen den Tumor an; dieselbe Immunaktivierung kann aber auch gesunde Organe entzünden (immunvermittelte Nebenwirkungen).","nebenwirkungen":{"sehrHaeufig":["Müdigkeit und Schwäche","Appetitlosigkeit","Übelkeit, Erbrechen, Durchfall","Husten, Atemnot","Hautausschlag, Juckreiz","Gelenk-, Rücken- und Muskelschmerzen","Fieber","Harnwegsinfektion"],"haeufig":["Hypothyreose (Schilddrüsenunterfunktion) oder Hyperthyreose (Überfunktion)","Pneumonitis (Lungenentzündung durch das Immunsystem)","Kolitis (Darmentzündung)","Erhöhte Leberwerte, Hepatitis","Infusionsreaktionen (Schüttelfrost, Fieber)","Thrombozytopenie (Mangel an Blutplättchen)","Hypokaliämie, Hyponatriämie (Kalium- und Natriummangel)","Hypotonie (tiefer Blutdruck)"],"gelegentlich":["Diabetes mellitus Typ 1 (plötzlich auftretend)","Nebenniereninsuffizienz","Pankreatitis (Bauchspeicheldrüsenentzündung)","Nephritis (Nierenentzündung)","Myositis (Muskelentzündung)","Schwere Hautreaktionen"],"selten":["Myokarditis (Herzmuskelentzündung)","Hypophysitis (Entzündung der Hirnanhangsdrüse)","Myasthenie-Syndrom, Guillain-Barré-Syndrom (Nervenlähmungen)","Meningoenzephalitis (Hirn- und Hirnhautentzündung)","Uveitis (Augenentzündung)"],"unbekannt":["Perikarderkrankungen (Herzbeutelentzündung)","Hämophagozytische Lymphohistiozytose (lebensbedrohliche Überaktivierung des Immunsystems)"]},"schwangerschaft":"Nicht anwenden, ausser der Nutzen überwiegt klar: PD-L1-Hemmung kann zum Verlust der Schwangerschaft führen. Sichere Verhütung während und bis 5 Monate nach der letzten Dosis.","stillzeit":"Übergang in die Muttermilch möglich; während der Behandlung nicht stillen.","hinweise":["Neue Beschwerden wie Husten, Atemnot, Durchfall, Bauchschmerzen, Gelbfärbung, starke Müdigkeit oder Kopfschmerzen sofort melden – auch nach Therapieende.","Vor jeder Gabe werden Leber-, Nieren- und Schilddrüsenwerte sowie der Blutzucker kontrolliert.","Alle Ärztinnen und Ärzte über die Immuntherapie informieren (Patientenkarte mitführen)."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"atomoxetin":{"wirkmechanismus":"Verbessert die Aufmerksamkeit und vermindert Impulsivität und Hyperaktivität, indem es den Botenstoff Noradrenalin im Gehirn länger wirken lässt. Atomoxetin hemmt selektiv den präsynaptischen Noradrenalin-Transporter; im Stirnhirn steigt dadurch auch Dopamin. Es ist kein Psychostimulans und hat kein relevantes Missbrauchspotenzial. Die volle Wirkung entwickelt sich über mehrere Wochen; abgebaut wird es hauptsächlich über CYP2D6.","nebenwirkungen":{"sehrHaeufig":["Appetitminderung","Kopfschmerzen","Übelkeit, Erbrechen, Bauchschmerzen","Schläfrigkeit (Kinder), Schlaflosigkeit (Erwachsene)","Mundtrockenheit (Erwachsene)","Anstieg von Blutdruck und Puls"],"haeufig":["Reizbarkeit, Stimmungsschwankungen, Unruhe, Angst, Depression","Tics","Schwindel, Zittern, Geschmacksstörungen","Pupillenerweiterung (Mydriasis)","Herzklopfen, Herzrasen, Hitzewallungen","Verstopfung, Dyspepsie (Verdauungsbeschwerden)","Hautausschlag, Juckreiz, vermehrtes Schwitzen","Erschwertes Wasserlassen, Harnverhalt (Erwachsene), Erektions- und Ejakulationsstörungen, Gewichtsabnahme"],"gelegentlich":["Suizidgedanken und suizidales Verhalten","Aggressivität, Feindseligkeit, Psychose mit Halluzinationen","Ohnmacht (Synkope), Krampfanfälle","QT-Verlängerung","Verschwommenes Sehen","Allergische Reaktionen","Atemnot"],"selten":["Schwere Leberschäden bis zum akuten Leberversagen, Gelbsucht","Raynaud-Phänomen (kalte, weisse Finger)","Priapismus (schmerzhafte Dauererektion)"]},"schwangerschaft":"Keine ausreichenden Daten; nicht anwenden, ausser nach strenger ärztlicher Abwägung.","stillzeit":"Ob Atomoxetin in die Muttermilch übergeht, ist nicht bekannt (im Tierversuch ja); während der Stillzeit nicht empfohlen.","hinweise":["Die Wirkung baut sich über mehrere Wochen auf; einmal täglich morgens oder auf zwei Dosen verteilt, mit oder ohne Essen einnehmen.","Kapseln nicht öffnen – der Inhalt reizt die Augen.","Bei Gelbsucht, dunklem Urin, Juckreiz oder Oberbauchschmerzen sofort ärztlich abklären lassen (Leberschaden).","Puls, Blutdruck, Gewicht und bei Kindern die Grösse regelmässig kontrollieren; auf Stimmungsveränderungen und Suizidgedanken achten."],"darreichung":["Kapseln"]},"atorvastatin":{"wirkmechanismus":"Senkt das Cholesterin, indem es dessen Herstellung in der Leber bremst. Atorvastatin hemmt selektiv und kompetitiv die HMG-CoA-Reduktase, das Schlüsselenzym der Cholesterinsynthese. Die Leberzellen bilden mehr LDL-Rezeptoren und holen vermehrt LDL-Cholesterin aus dem Blut; zusätzlich sinken die Triglyceride. Atorvastatin wird über CYP3A4 zu ebenfalls wirksamen Metaboliten abgebaut und über den Transporter OATP1B1 in die Leber aufgenommen – Hemmer dieser Wege erhöhen die Spiegel und das Risiko für Muskelschäden.","nebenwirkungen":{"haeufig":["Nasopharyngitis (Nasen-Rachen-Entzündung), Halsschmerzen, Nasenbluten","Allergische Reaktionen","Hyperglykämie (erhöhter Blutzucker)","Kopfschmerzen","Verstopfung, Blähungen, Verdauungsbeschwerden, Übelkeit, Durchfall","Muskel- und Gelenkschmerzen, Gliederschmerzen, Muskelkrämpfe, Gelenkschwellung, Rückenschmerzen","Abweichende Leberwerte, erhöhte CK (Muskelenzym)"],"gelegentlich":["Hypoglykämie (Unterzuckerung), Gewichtszunahme, Appetitlosigkeit","Albträume, Schlaflosigkeit","Schwindel, Kribbeln, Taubheitsgefühl, Geschmacksstörung, Gedächtnisverlust","Verschwommenes Sehen, Tinnitus (Ohrgeräusche)","Erbrechen, Bauchschmerzen, Aufstossen, Pankreatitis (Bauchspeicheldrüsenentzündung)","Hepatitis (Leberentzündung)","Nesselsucht, Ausschlag, Juckreiz, Haarausfall","Nackenschmerzen, Muskelermüdung, Unwohlsein, Schwäche, Brustschmerzen, Ödeme, Müdigkeit, Fieber"],"selten":["Myopathie, Myositis, Rhabdomyolyse (Muskelzerfall), Muskelriss","Tendinopathie (Sehnenschäden), teils mit Sehnenriss","Thrombozytopenie (Mangel an Blutplättchen)","Periphere Neuropathie, Sehstörungen","Cholestase (Gallestau)","Angioödem; blasenbildende Hautreaktionen bis zu Stevens-Johnson-Syndrom und toxischer epidermaler Nekrolyse"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Leberversagen","Hörverlust","Gynäkomastie (Brustvergrösserung beim Mann)"],"unbekannt":["Immunvermittelte nekrotisierende Myopathie (anhaltende Muskelschwäche)","Myasthenia gravis (Muskelschwäche), auch am Auge, oder deren Verschlechterung","Depression, sexuelle Funktionsstörungen, interstitielle Lungenerkrankung (Klasseneffekte der Statine)","Diabetes mellitus bei Personen mit Risikofaktoren"]},"schwangerschaft":"Kontraindiziert – Cholesterin ist für die Entwicklung des Ungeborenen nötig. Frauen im gebärfähigen Alter müssen zuverlässig verhüten; bei Eintritt einer Schwangerschaft sofort absetzen.","stillzeit":"Kontraindiziert – Übergang in die Muttermilch beim Menschen nicht bekannt, schwere Nebenwirkungen beim Säugling möglich.","hinweise":["Einmal täglich zu einer beliebigen, aber gleichbleibenden Tageszeit, mit oder ohne Essen.","Unerklärliche Muskelschmerzen, -schwäche oder -krämpfe, besonders mit Fieber oder dunklem Urin, sofort ärztlich melden.","Grosse Mengen Grapefruitsaft meiden; neue Medikamente (Antibiotika, Pilzmittel, HIV- oder Hepatitis-C-Mittel) auf Wechselwirkungen prüfen lassen.","Leberwerte vor Behandlungsbeginn und bei Bedarf kontrollieren; Ernährung und Bewegung bleiben wichtig."],"darreichung":["Filmtabletten"]},"atovaquon-proguanil":{"wirkmechanismus":"Tötet Malariaerreger im Blut und bereits in der Leber ab. Atovaquon hemmt selektiv den Elektronentransport in den Mitochondrien des Parasiten (Cytochrom-bc1-Komplex) und damit dessen Energiestoffwechsel und Pyrimidinsynthese. Proguanil verstärkt diese Wirkung auf das Mitochondrienmembranpotential; sein Metabolit Cycloguanil hemmt zusätzlich die Dihydrofolatreduktase des Erregers. Weil auch die Leberstadien erfasst werden, genügt nach der Rückkehr eine Einnahme über 7 Tage.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Bauchschmerzen","Übelkeit, Erbrechen","Durchfall"],"haeufig":["Schwindel","Schlaflosigkeit, ungewöhnliche Träume, Depression","Appetitlosigkeit","Husten","Fieber","Hautausschlag, Juckreiz","Erhöhte Leberwerte","Blutarmut (Anämie), Neutropenie, Hyponatriämie (Natriummangel)"],"gelegentlich":["Angst","Herzklopfen","Mundschleimhautentzündung (Stomatitis)","Haarausfall","Nesselsucht","Erhöhte Amylase-Werte"],"selten":["Halluzinationen"],"unbekannt":["Anaphylaxie, Angioödem, Vaskulitis","Stevens-Johnson-Syndrom, Erythema multiforme","Krampfanfälle","Panikattacken","Hepatitis, Gallenstau (Cholestase)","Herzrasen (Tachykardie)","Panzytopenie bei schwerer Niereninsuffizienz"]},"schwangerschaft":"Die Sicherheit ist nicht belegt. Nur anwenden, wenn der erwartete Nutzen das mögliche Risiko für das Kind überwiegt; Schwangere sollten Reisen in Malariagebiete möglichst vermeiden.","stillzeit":"Soll während der Stillzeit nicht eingenommen werden.","hinweise":["Täglich zur gleichen Zeit mit einer Mahlzeit oder einem Milchgetränk einnehmen – das verbessert die Aufnahme von Atovaquon.","Bei Erbrechen innerhalb einer Stunde nach der Einnahme eine weitere Dosis einnehmen.","Vorbeugung 1–2 Tage vor der Einreise beginnen und bis 7 Tage nach Verlassen des Malariagebiets fortsetzen; Mückenschutz bleibt wichtig.","Fieber während oder nach einer Tropenreise sofort ärztlich abklären lassen."],"darreichung":["Filmtabletten"]},"atropin":{"wirkmechanismus":"Blockiert den Botenstoff Acetylcholin an den Organen, die vom «Ruhenerv» (Parasympathikus) gesteuert werden: Das Herz schlägt schneller, Speichel-, Schweiss- und Bronchialsekretion nehmen ab, Darm und Blase erschlaffen, die Pupille wird weit. Atropin ist ein kompetitiver Antagonist an allen Muskarinrezeptor-Subtypen (M1–M5). Als tertiäres Amin gelangt es ins Gehirn und kann in höheren Dosen Unruhe, Verwirrtheit und Halluzinationen auslösen. Bei Vergiftungen mit Cholinesterasehemmern hebt es die Überstimulation der Muskarinrezeptoren auf (nicht aber die Muskelschwäche an den Nikotinrezeptoren).","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit, verminderte Speichelbildung","Sehstörungen durch Pupillenerweiterung und Akkommodationslähmung, Lichtempfindlichkeit","Vermindertes Schwitzen mit Hautrötung und Wärmestau"],"haeufig":["Tachykardie (Herzrasen)","Schluckbeschwerden","Verstopfung, Reflux"],"gelegentlich":["Harnverhalt, Schwierigkeiten beim Wasserlassen","Allergische Reaktionen, Hautausschlag"],"selten":["Unruhe, Erregung, Verwirrtheit, Halluzinationen (vor allem bei hohen Dosen und älteren Menschen)","Krampfanfälle","Glaukomanfall (akuter Anstieg des Augeninnendrucks)"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Kurzzeitige paradoxe Verlangsamung des Pulses bei sehr niedrigen Dosen","Herzrhythmusstörungen, Kammerflimmern","Augentropfen: Bindehautreizung, Lidschwellung, Kontaktallergie"]},"schwangerschaft":"Atropin geht auf das Ungeborene über und kann dessen Herzschlag beschleunigen. Nur bei klarer Notwendigkeit, z. B. im Notfall oder bei Narkosen, anwenden.","stillzeit":"Geht in die Muttermilch über und kann die Milchbildung hemmen. Einmalige Gaben (z. B. bei Narkose) sind meist unproblematisch; bei wiederholter Anwendung ärztlich abwägen.","hinweise":["Nach Atropin-Augentropfen bleiben Sehen und Blendempfindlichkeit oft 7–14 Tage beeinträchtigt: in dieser Zeit nicht Auto fahren, Sonnenbrille tragen.","Bei Augentropfen den inneren Augenwinkel 1–2 Minuten zudrücken, damit weniger Wirkstoff in den Körper gelangt – besonders wichtig bei Kindern.","Bei lebensbedrohlichen Zuständen (Vergiftung, Herzstillstand) gelten die Gegenanzeigen nicht absolut – der Nutzen geht vor.","Augenschmerzen mit Sehverschlechterung und rotem Auge sofort ärztlich abklären (Glaukomanfall)."],"darreichung":["Injektionslösung","Augentropfen"]},"avalglucosidase-alfa":{"wirkmechanismus":"Ersetzt ein Enzym, das bei Morbus Pompe fehlt, damit sich weniger Glykogen (Speicherzucker) in den Muskelzellen ablagert. Avalglucosidase alfa ist eine gentechnisch hergestellte saure Alpha-Glucosidase, an die zusätzliche Zuckerketten mit Bis-Mannose-6-Phosphat gekoppelt sind. Dadurch wird sie über Mannose-6-Phosphat-Rezeptoren deutlich besser in Skelett-, Herz- und Atemmuskulatur aufgenommen. In den Lysosomen spaltet sie Glykogen zu Glukose.","nebenwirkungen":{"haeufig":["Überempfindlichkeitsreaktionen, auch Anaphylaxie","Kopfschmerzen, Schwindel, Zittern, Schläfrigkeit, Kribbeln","Augenrötung, Lidschwellung","Herzrasen, Blutdruckanstieg oder -abfall, Hautrötung mit Hitzegefühl","Husten, Atemnot, Rachenreizung","Übelkeit, Erbrechen, Durchfall, Lippen- oder Zungenschwellung","Juckreiz, Ausschlag, Nesselsucht, vermehrtes Schwitzen","Schüttelfrost, Fieber, Müdigkeit, Brustbeschwerden, Muskelschmerzen"]},"schwangerschaft":"Nur begrenzte Erfahrungen. Anwendung nur nach ärztlicher Abwägung, wenn der Nutzen das Risiko überwiegt.","stillzeit":"Nur begrenzte Daten. Entscheid über Stillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Wird alle 2 Wochen als Infusion in eine Vene gegeben; die Infusionsgeschwindigkeit wird schrittweise gesteigert.","Infusionsreaktionen können noch Stunden nach der Infusion auftreten – Beschwerden sofort melden.","Antikörper und Urin werden regelmässig kontrolliert."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Infusionslösung"]},"avanafil":{"wirkmechanismus":"Verbessert bei sexueller Erregung den Blutfluss in den Penis und ermöglicht so eine Erektion. Avanafil hemmt selektiv die Phosphodiesterase 5, die im Schwellkörper den Botenstoff cGMP abbaut. Bei sexueller Stimulation freigesetztes Stickstoffmonoxid erhöht cGMP, das die glatte Muskulatur entspannt und den Bluteinstrom steigert; Avanafil verstärkt diesen Effekt. Ohne sexuelle Stimulation wirkt es nicht; die Wirkung setzt nach etwa 15–30 Minuten ein.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Flush (Gesichtsrötung)","Verstopfte Nase"],"gelegentlich":["Schwindel, Schläfrigkeit","Verschwommenes Sehen","Herzklopfen","Hitzewallungen","Dyspepsie (Verdauungsbeschwerden), Übelkeit, Erbrechen","Rückenschmerzen, Muskelverspannung","Müdigkeit","Erhöhte Leberwerte"],"selten":["Angina pectoris, Herzrasen","Bluthochdruck","Brustschmerzen","Hautausschlag","Spontane Erektionen"],"unbekannt":["Plötzlicher Sehverlust (NAION, bei PDE-5-Hemmern beschrieben)","Plötzliche Hörminderung","Priapismus (schmerzhafte Dauererektion über 4 Stunden)"]},"schwangerschaft":"Nicht für Frauen bestimmt.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Etwa 15–30 Minuten vor dem Geschlechtsverkehr einnehmen, höchstens einmal täglich.","Grapefruitsaft 24 Stunden vor der Einnahme meiden; Alkohol kann den Blutdruck zusätzlich senken.","Bei Erektion über 4 Stunden oder plötzlichem Seh- oder Hörverlust sofort ärztliche Hilfe holen.","Im Notfall (z. B. Brustschmerzen) die Einnahme angeben: Nitrate dürfen frühestens 12 Stunden nach Avanafil gegeben werden."],"darreichung":["Tabletten"]},"avatrombopag":{"wirkmechanismus":"Regt das Knochenmark an, mehr Blutplättchen zu bilden. Avatrombopag ist ein oral wirksames kleines Molekül, das an die Transmembrandomäne des Thrombopoetin-Rezeptors (c-Mpl) bindet. Es fördert Vermehrung und Reifung der Megakaryozyten und damit die Thrombozytenbildung, ohne mit dem körpereigenen Thrombopoetin um dieselbe Bindungsstelle zu konkurrieren. Die Plättchenzahl steigt nach einigen Tagen an und erreicht ihr Maximum nach etwa 10–13 Tagen.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit (v. a. bei ITP-Behandlung)","Kopfschmerzen (v. a. bei ITP-Behandlung)"],"haeufig":["Nasenbluten","Übelkeit, Durchfall, Erbrechen, Bauchschmerzen","Gelenk-, Rücken- und Muskelschmerzen","Hautausschlag, Juckreiz","Schwindel, Migräne","Wassereinlagerungen (Ödeme)","Anstieg der Blutplättchen über den Zielbereich (Thrombozytose)"],"gelegentlich":["Thrombosen und Embolien (z. B. Pfortaderthrombose, tiefe Venenthrombose, Lungenembolie)","Blutarmut (Anämie)","Fieber","Knochenschmerzen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; im Tierversuch schädliche Wirkungen. Während der Schwangerschaft nicht empfohlen; Frauen im gebärfähigen Alter sollen verhüten.","stillzeit":"Ein Risiko für den Säugling kann nicht ausgeschlossen werden; während der Behandlung nicht stillen.","hinweise":["Mit einer Mahlzeit einnehmen.","Vor einem Eingriff bei Lebererkrankung wird es 5 Tage lang eingenommen; der Eingriff erfolgt 5–8 Tage nach der letzten Dosis.","Bei ITP Plättchenzahl regelmässig kontrollieren und nicht eigenmächtig absetzen."],"darreichung":["Filmtabletten"]},"azathioprin":{"wirkmechanismus":"Bremst die Vermehrung von Abwehrzellen und dämpft so überschiessende Immunreaktionen. Azathioprin ist ein Prodrug, das im Körper zu 6-Mercaptopurin und weiter zu Thioguanin-Nukleotiden umgewandelt wird. Diese werden als falsche Bausteine in die Erbsubstanz eingebaut und hemmen die Purin-Neusynthese, wodurch besonders sich teilende T- und B-Lymphozyten gebremst werden. Der volle Effekt tritt erst nach Wochen bis Monaten ein.","nebenwirkungen":{"sehrHaeufig":["Infektionen (Viren, Pilze, Bakterien), v. a. nach Transplantation","Leukopenie (Mangel an weissen Blutkörperchen) durch Knochenmarkhemmung"],"haeufig":["Thrombozytopenie (Mangel an Blutplättchen)","Übelkeit (v. a. zu Beginn)"],"gelegentlich":["Anämie","Überempfindlichkeitsreaktionen mit Fieber, Schwindel, Erbrechen, Durchfall, Muskel- und Gelenkschmerzen, Ausschlag, Blutdruckabfall","Pankreatitis (Bauchspeicheldrüsenentzündung)","Cholestase (Gallenstau) und erhöhte Leberwerte"],"selten":["Agranulozytose, Panzytopenie, aplastische Anämie, megaloblastäre Anämie","Bösartige Tumoren (Lymphome, Hautkrebs, Sarkome)","Lebervenenverschlusskrankheit (lebensbedrohliche Leberschädigung)","Kolitis, Divertikulitis, Darmdurchbruch (nach Transplantation)","Haarausfall"],"sehrSelten":["Pneumonitis (nicht-infektiöse Lungenentzündung)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse"],"unbekannt":["Hepatosplenisches T-Zell-Lymphom","Progressive multifokale Leukenzephalopathie (PML)","Sweet-Syndrom (akute fieberhafte Hauterkrankung)","Lichtempfindlichkeit"]},"schwangerschaft":"Nur nach sorgfältiger ärztlicher Abwägung; bei Transplantation und chronisch entzündlichen Darmerkrankungen wird die Therapie oft fortgeführt. Beim Neugeborenen sind Blutbildveränderungen möglich.","stillzeit":"Geringe Mengen des Metaboliten Mercaptopurin gehen in die Muttermilch über; Stillen nur nach ärztlicher Abwägung, Säugling beobachten.","hinweise":["Vor Beginn TPMT/NUDT15 bestimmen lassen; Blutbild in den ersten 8 Wochen wöchentlich, danach regelmässig kontrollieren.","Fieber, Halsschmerzen, blaue Flecken oder Blutungen sofort ärztlich melden.","Konsequenter Sonnenschutz und jährliche Hautkontrolle.","Nach dem Essen einnehmen (bessere Magenverträglichkeit); Tabletten nicht teilen oder zerkleinern."],"darreichung":["Filmtabletten","Pulver zur Herstellung einer Injektionslösung"]},"azelainsaeure":{"wirkmechanismus":"Wirkt gegen Aknebakterien, Entzündung und Verhornungsstörungen in den Talgdrüsenfollikeln. Azelainsäure ist eine natürlich vorkommende Dicarbonsäure, die das Wachstum von Cutibacterium acnes und Staphylococcus epidermidis hemmt (u. a. über eine Hemmung der bakteriellen Eiweisssynthese) und die übermässige Verhornung der Follikelwand normalisiert. Zusätzlich vermindert sie entzündungsfördernde Sauerstoffradikale, was bei der Rosazea im Vordergrund steht. Nur ein kleiner Teil wird über die Haut aufgenommen.","nebenwirkungen":{"sehrHaeufig":["Brennen, Juckreiz, Schmerzen und Rötung an der Auftragsstelle"],"haeufig":["Schuppung und Trockenheit der Haut","Kribbeln (Parästhesie), Hautausschlag","Hautreizung, Verfärbung der Haut"],"gelegentlich":["Hautentzündung (Dermatitis), Schwellung (Ödem)","Akne, vermehrte Talgbildung (Seborrhö)","Hellere Hautflecken (Depigmentierung)"],"selten":["Lippenentzündung (Cheilitis)","Überempfindlichkeitsreaktionen mit Angioödem, Gesichts- oder Augenschwellung, Atemnot"],"unbekannt":["Verschlechterung eines Asthmas"]},"schwangerschaft":"Nach ärztlicher Abwägung möglich; es gelangt nur wenig Wirkstoff in den Körper.","stillzeit":"Nach Abwägung möglich; nicht auf die Brust auftragen, der Säugling darf nicht mit behandelter Haut in Kontakt kommen.","hinweise":["Zweimal täglich dünn auf die gereinigte Haut auftragen und einmassieren; danach Hände waschen.","Brennen und Juckreiz zu Beginn sind häufig und klingen meist nach einigen Tagen ab.","Die Wirkung zeigt sich meist nach etwa 4 Wochen; regelmässig anwenden.","Keine luftdichten Verbände; bei Rosazea alkoholhaltige Reinigungsmittel und reizende Kosmetika meiden."],"darreichung":["Creme (20 %)","Gel (15 %)"]},"azelastin":{"wirkmechanismus":"Lindert rasch Niesen, Juckreiz, Fliessschnupfen und tränende Augen. Azelastin blockiert H1-Rezeptoren und verhindert so die Wirkung von Histamin an Nasenschleimhaut und Bindehaut. Zusätzlich hemmt es die Freisetzung weiterer Entzündungsstoffe (z. B. Leukotriene) aus Mastzellen. Die Wirkung setzt nach etwa 15 Minuten ein.","nebenwirkungen":{"haeufig":["Bitterer Geschmack nach dem Sprühen","Leichtes, vorübergehendes Brennen oder Jucken der Augen nach dem Eintropfen"],"gelegentlich":["Reizung der Nasenschleimhaut (Brennen, Kribbeln), Niesen","Nasenbluten"],"sehrSelten":["Überempfindlichkeitsreaktionen (Ausschlag, Juckreiz, Nesselsucht)","Müdigkeit, Schwindel","Übelkeit"]},"schwangerschaft":"Nur nach ärztlicher Abwägung, besonders im ersten Schwangerschaftsdrittel zurückhaltend.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; nur nach ärztlicher Abwägung.","hinweise":["Beim Sprühen den Kopf aufrecht halten und das Spray nicht hochziehen – das vermindert den bitteren Geschmack.","Kontaktlinsen vor dem Eintropfen herausnehmen und frühestens nach 15 Minuten wieder einsetzen.","Bei Heuschnupfen während der Pollensaison regelmässig anwenden."],"darreichung":["Nasenspray","Augentropfen"]},"azelastin-fluticason":{"wirkmechanismus":"Kombiniert eine rasch einsetzende antiallergische mit einer anhaltend entzündungshemmenden Wirkung. Azelastin blockiert H1-Rezeptoren und hemmt die Freisetzung von Entzündungsstoffen aus Mastzellen; es lindert Niesen und Juckreiz innerhalb von Minuten. Fluticasonpropionat bindet an den Glukokortikoidrezeptor und dämpft die allergische Entzündung der Nasenschleimhaut. Verschluckter Wirkstoff wird in der Leber über CYP3A4 weitgehend abgebaut.","nebenwirkungen":{"haeufig":["Nasenbluten","Kopfschmerzen","Bitterer Geschmack (Dysgeusie), unangenehmer Geruch"],"gelegentlich":["Brennen, Jucken oder Trockenheit in der Nase, Niesen","Husten, Halstrockenheit, Rachenreizung"],"selten":["Mundtrockenheit"],"sehrSelten":["Überempfindlichkeitsreaktionen bis Anaphylaxie, Angioödem","Schwindel, Schläfrigkeit, Müdigkeit","Katarakt, Glaukom, erhöhter Augendruck","Durchbruch der Nasenscheidewand, Schleimhautschäden","Bronchospasmus (Verkrampfung der Atemwege)"],"unbekannt":["Verschwommenes Sehen","Geschwüre der Nasenschleimhaut"]},"schwangerschaft":"Nur nach ärztlicher Abwägung, wenn der Nutzen das mögliche Risiko überwiegt.","stillzeit":"Nur nach ärztlicher Abwägung; ob die Wirkstoffe in die Muttermilch übergehen, ist nicht ausreichend bekannt.","hinweise":["Vor jedem Gebrauch schütteln; beim Sprühen den Kopf leicht nach vorne neigen und das Spray nicht hochziehen.","Regelmässig anwenden, solange Allergenkontakt besteht – auch wenn die Beschwerden nachlassen.","Eine Ritonavir- oder Cobicistat-haltige HIV-Therapie vor Behandlungsbeginn ärztlich angeben."],"darreichung":["Nasenspray (Suspension)"]},"azithromycin":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien, indem es ihre Eiweissherstellung stoppt. Azithromycin bindet an die 50S-Untereinheit der bakteriellen Ribosomen und blockiert die Verlängerung der Eiweisskette. Es reichert sich stark im Gewebe und in Abwehrzellen an und wird sehr langsam ausgeschieden (Halbwertszeit rund 2–3 Tage), daher die kurze Behandlungsdauer. Anders als Clarithromycin und Erythromycin hemmt es CYP3A4 kaum.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Bei Augentropfen: Brennen, Stechen oder Reizung am Auge"],"haeufig":["Übelkeit, Erbrechen, Bauchschmerzen","Kopfschmerzen","Veränderte Laborwerte (weniger Lymphozyten, mehr Eosinophile, tieferes Bikarbonat)"],"gelegentlich":["Pilzinfektionen (Candidose), Scheideninfektion","Schwindel, Schläfrigkeit, Geschmacksstörungen, Kribbeln","Hörstörungen, Drehschwindel","Herzklopfen","Hepatitis (Leberentzündung), erhöhte Leberwerte","Hautausschlag, Juckreiz, Nesselsucht","Angioödem, Überempfindlichkeitsreaktionen","Leukopenie, Neutropenie (weniger weisse Blutkörperchen)"],"selten":["Unruhe (Agitiertheit)","Cholestatische Gelbsucht","Lichtempfindlichkeit der Haut","DRESS und akute generalisierte exanthematische Pustulose (schwere Hautreaktionen)"],"unbekannt":["QT-Verlängerung, Torsade de pointes und andere Herzrhythmusstörungen","Leberversagen, fulminante Hepatitis","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Anaphylaxie (schwere allergische Reaktion)","Hörverlust bis Taubheit, Tinnitus","Pseudomembranöse Kolitis, Pankreatitis","Thrombozytopenie, hämolytische Anämie","Krampfanfälle, Verschlechterung einer Myasthenia gravis, akutes Nierenversagen"]},"schwangerschaft":"Grosse Beobachtungsstudien zeigen kein erhöhtes Fehlbildungsrisiko, die Daten sind aber nicht abschliessend. Nur bei klarer Notwendigkeit nach ärztlicher Abwägung; Augentropfen sind vertretbar.","stillzeit":"Geht in die Muttermilch über; beim Säugling sind Durchfall und Pilzbefall möglich. Nach ärztlicher Abwägung anwendbar, Kind beobachten.","hinweise":["Die Wirkung hält nach der letzten Dosis noch mehrere Tage an – die Packung trotzdem wie verordnet vollständig einnehmen.","Antazida (Magensäurebinder) nicht gleichzeitig einnehmen.","Bei Herzklopfen, Ohnmacht, Gelbsucht oder schwerem Hautausschlag sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten","Pulver für Suspension zum Einnehmen","Pulver zur Herstellung einer Infusionslösung","Augentropfen (Einzeldosen)"]}});
